window.QBANK = window.QBANK || {};
window.QBANK["sma-kimia"] = {
  level: "SMA", subject: "Kimia", duration: 900,
  questions: [
    { q: "Massa molekul relatif ($M_r$) dari H₂SO₄ adalah ... ($A_r$: H = 1, S = 32, O = 16)", options: ["96", "98", "100", "49"], answer: 1, solution: "Langkah 1: catat $A_r$ tiap unsur, H = 1, S = 32, O = 16. Langkah 2: $M_r = 2(A_r\\ \\text{H}) + A_r\\ \\text{S} + 4(A_r\\ \\text{O}) = 2(1) + 32 + 4(16)$. Langkah 3: $= 2 + 32 + 64 = 98$." },
    { q: "Jumlah mol dalam $4$ gram NaOH adalah ... ($M_r$ NaOH = 40)", options: ["0,4 mol", "10 mol", "0,1 mol", "1 mol"], answer: 2, solution: "Langkah 1: diketahui massa $= 4\\ \\text{g}$ dan $M_r = 40$. Langkah 2: gunakan rumus $n = \\frac{\\text{massa}}{M_r} = \\frac{4}{40}$. Langkah 3: $n = 0{,}1\\ \\text{mol}$." },
    { q: "pH larutan HCl $0{,}01\\ \\text{M}$ adalah ...", options: ["1", "12", "2", "4"], answer: 2, solution: "Langkah 1: HCl adalah asam kuat bervalensi 1, jadi $[H^+] = 0{,}01\\ \\text{M} = 10^{-2}\\ \\text{M}$. Langkah 2: $pH = -\\log[H^+] = -\\log 10^{-2}$. Langkah 3: $pH = 2$." },
    { q: "Di antara zat berikut, yang merupakan asam lemah adalah ...", options: ["HCl", "H₂SO₄", "HNO₃", "CH₃COOH"], answer: 3, solution: "Langkah 1: asam kuat terionisasi sempurna dalam air, contohnya HCl, H₂SO₄, dan HNO₃. Langkah 2: asam lemah hanya terionisasi sebagian. Langkah 3: CH₃COOH (asam cuka) terionisasi sebagian, jadi ia asam lemah." },
    { q: "Bilangan oksidasi belerang (S) dalam H₂SO₄ adalah ...", options: ["+4", "+2", "−2", "+6"], answer: 3, solution: "Langkah 1: aturan biloks, H $= +1$ dan O $= -2$. Langkah 2: misalkan biloks S $= x$, maka $2(+1) + x + 4(-2) = 0$. Langkah 3: $2 + x - 8 = 0$, sehingga $x = +6$." },
    { q: "Reaksi: $2\\text{H}_2 + \\text{O}_2 \\to 2\\text{H}_2\\text{O}$. Jika $4$ gram H₂ direaksikan sempurna, massa H₂O yang terbentuk adalah ... ($M_r$: H₂ = 2, H₂O = 18)", options: ["36 g", "18 g", "72 g", "9 g"], answer: 0, solution: "Langkah 1: $n(\\text{H}_2) = \\frac{4}{2} = 2\\ \\text{mol}$. Langkah 2: perbandingan koefisien $\\text{H}_2 : \\text{H}_2\\text{O} = 2 : 2 = 1 : 1$, jadi $n(\\text{H}_2\\text{O}) = 2\\ \\text{mol}$. Langkah 3: massa $= n \\times M_r = 2 \\times 18 = 36\\ \\text{g}$." },
    { q: "Konsentrasi larutan yang mengandung $0{,}5$ mol zat dalam $2$ liter larutan adalah ...", options: ["1 M", "0,25 M", "2,5 M", "0,5 M"], answer: 1, solution: "Langkah 1: gunakan rumus molaritas $M = \\frac{n}{V}$. Langkah 2: $M = \\frac{0{,}5}{2}$. Langkah 3: $M = 0{,}25\\ \\text{M}$." },
    { q: "Dalam reaksi redoks, oksidasi adalah peristiwa ...", options: ["pelepasan elektron", "penangkapan elektron", "penurunan bilangan oksidasi", "penambahan atom hidrogen"], answer: 0, solution: "Langkah 1: reaksi redoks melibatkan transfer elektron. Langkah 2: oksidasi ditandai kenaikan bilangan oksidasi. Langkah 3: bilangan oksidasi naik karena atom melepaskan elektron, jadi oksidasi = pelepasan elektron." },
    { q: "pH larutan NaOH $0{,}001\\ \\text{M}$ adalah ...", options: ["11", "3", "1", "13"], answer: 0, solution: "Langkah 1: NaOH basa kuat bervalensi 1, jadi $[OH^-] = 0{,}001\\ \\text{M} = 10^{-3}\\ \\text{M}$. Langkah 2: $pOH = -\\log[OH^-] = -\\log 10^{-3} = 3$. Langkah 3: $pH = 14 - pOH = 14 - 3 = 11$." },
    { q: "Hukum Lavoisier (hukum kekekalan massa) menyatakan bahwa ...", options: ["massa zat berkurang setelah reaksi", "massa zat sebelum dan sesudah reaksi adalah sama", "volume gas selalu tetap", "jumlah mol zat selalu bertambah"], answer: 1, solution: "Langkah 1: Hukum Lavoisier membahas kekekalan massa dalam reaksi kimia. Langkah 2: dalam sistem tertutup tidak ada massa yang hilang atau bertambah. Langkah 3: jadi massa total zat sebelum reaksi sama dengan massa total zat sesudah reaksi." },
    { q: "Partikel penyusun atom yang bermuatan positif adalah ...", options: ["elektron", "neutron", "proton", "foton"], answer: 2, solution: "Langkah 1: atom tersusun dari proton, neutron, dan elektron. Langkah 2: proton bermuatan positif dan terletak di inti atom, elektron bermuatan negatif, neutron tidak bermuatan. Langkah 3: jadi partikel bermuatan positif adalah proton." },
    { q: "Unsur dengan nomor atom $11$ terletak pada golongan ...", options: ["IIA", "IA", "IIIA", "VIIIA"], answer: 1, solution: "Langkah 1: unsur bernomor atom $11$ adalah natrium (Na) dengan konfigurasi elektron $2, 8, 1$. Langkah 2: jumlah elektron valensi $= 1$. Langkah 3: unsur dengan $1$ elektron valensi terletak pada golongan IA." },
    { q: "Unsur X memiliki konfigurasi elektron $2, 8, 1$. Unsur X terletak pada periode ...", options: ["$1$", "$2$", "$3$", "$4$"], answer: 2, solution: "Langkah 1: periode ditentukan oleh jumlah kulit elektron yang terisi. Langkah 2: konfigurasi $2, 8, 1$ menunjukkan ada $3$ kulit elektron. Langkah 3: jadi unsur X terletak pada periode $3$." },
    { q: "Ikatan kimia yang terjadi karena adanya serah terima elektron antara atom logam dan nonlogam adalah ikatan ...", options: ["kovalen", "ion", "logam", "hidrogen"], answer: 1, solution: "Langkah 1: ikatan ion terbentuk ketika atom logam melepaskan elektron dan atom nonlogam menangkap elektron. Langkah 2: serah terima elektron menghasilkan ion positif dan ion negatif yang saling tarik. Langkah 3: jadi ikatan tersebut adalah ikatan ion." },
    { q: "Di antara pasangan senyawa berikut, yang keduanya berikatan kovalen adalah ...", options: ["NaCl dan MgO", "H₂O dan CO₂", "NaCl dan H₂O", "MgO dan CaO"], answer: 1, solution: "Langkah 1: ikatan kovalen terjadi karena pemakaian elektron bersama, umumnya antara unsur nonlogam. Langkah 2: NaCl, MgO, dan CaO tersusun dari logam + nonlogam sehingga berikatan ion. Langkah 3: H₂O dan CO₂ tersusun dari nonlogam + nonlogam, jadi keduanya berikatan kovalen." },
    { q: "Reaksi: N₂ + 3H₂ → 2NH₃. Jika $6$ mol H₂ bereaksi sempurna, jumlah mol NH₃ yang terbentuk adalah ...", options: ["$3$ mol", "$4$ mol", "$6$ mol", "$9$ mol"], answer: 1, solution: "Langkah 1: perbandingan koefisien H₂ : NH₃ $= 3 : 2$. Langkah 2: mol NH₃ $= \\frac{2}{3} \\times$ mol H₂ $= \\frac{2}{3} \\times 6$. Langkah 3: $= 4$ mol." },
    { q: "Pada suhu dan tekanan yang sama, $2$ liter gas H₂ bereaksi dengan O₂ berlebih menurut reaksi $2\\text{H}_2 + \\text{O}_2 \\to 2\\text{H}_2\\text{O}$. Volume uap H₂O yang terbentuk adalah ...", options: ["$1$ L", "$2$ L", "$4$ L", "$0{,}5$ L"], answer: 1, solution: "Langkah 1: menurut hukum Avogadro, pada T dan P sama perbandingan volume gas = perbandingan koefisien. Langkah 2: perbandingan koefisien H₂ : H₂O $= 2 : 2$. Langkah 3: volume H₂O $= \\frac{2}{2} \\times 2\\ \\text{L} = 2\\ \\text{L}$." },
    { q: "$100$ mL larutan $2$ M diencerkan dengan air hingga volumenya $500$ mL. Konsentrasi larutan setelah pengenceran adalah ...", options: ["$1$ M", "$0{,}4$ M", "$10$ M", "$2{,}5$ M"], answer: 1, solution: "Langkah 1: gunakan rumus pengenceran $M_1 V_1 = M_2 V_2$. Langkah 2: $2 \\times 100 = M_2 \\times 500$. Langkah 3: $M_2 = \\frac{200}{500} = 0{,}4\\ \\text{M}$." },
    { q: "Menurut teori Arrhenius, basa adalah zat yang ...", options: ["menghasilkan ion H⁺ dalam air", "menghasilkan ion OH⁻ dalam air", "menerima proton (H⁺)", "mendonor pasangan elektron"], answer: 1, solution: "Langkah 1: teori Arrhenius mendefinisikan asam-basa berdasarkan ion yang dihasilkan dalam air. Langkah 2: asam menghasilkan ion H⁺, sedangkan basa menghasilkan ion OH⁻. Langkah 3: jadi menurut Arrhenius, basa menghasilkan ion OH⁻ dalam air." },
    { q: "pH larutan H₂SO₄ $0{,}05$ M adalah ...", options: ["$1$", "$2$", "$1{,}3$", "$13$"], answer: 0, solution: "Langkah 1: H₂SO₄ adalah asam kuat diprotik (bervalensi $2$), jadi $[H^+] = 2 \\times 0{,}05\\ \\text{M} = 0{,}1\\ \\text{M} = 10^{-1}\\ \\text{M}$. Langkah 2: $pH = -\\log[H^+] = -\\log 10^{-1}$. Langkah 3: $pH = 1$." },
    { q: "Reaksi: Zn + Cu²⁺ → Zn²⁺ + Cu. Zat yang bertindak sebagai oksidator adalah ...", options: ["Zn", "Cu²⁺", "Zn²⁺", "Cu"], answer: 1, solution: "Langkah 1: oksidator adalah zat yang mengalami reduksi (biloks turun). Langkah 2: biloks Cu turun dari $+2$ menjadi $0$, sedangkan biloks Zn naik dari $0$ menjadi $+2$. Langkah 3: jadi oksidatornya adalah Cu²⁺." },
    { q: "Pada sel volta, elektrode tempat terjadinya reaksi oksidasi sekaligus sebagai kutub negatif adalah ...", options: ["katode", "anode", "jembatan garam", "elektrolit"], answer: 1, solution: "Langkah 1: oksidasi selalu terjadi di anode. Langkah 2: pada sel volta (sel galvani), anode bermuatan negatif dan katode bermuatan positif. Langkah 3: jadi elektrode tersebut adalah anode." },
    { q: "Suatu reaksi kimia ditandai dengan $\\Delta H$ negatif. Reaksi tersebut tergolong reaksi ...", options: ["endoterm", "eksoterm", "netral", "reversibel"], answer: 1, solution: "Langkah 1: $\\Delta H$ negatif artinya entalpi produk lebih kecil dari entalpi pereaksi. Langkah 2: selisih entalpi dilepaskan sistem ke lingkungan sebagai kalor. Langkah 3: reaksi yang melepaskan kalor disebut reaksi eksoterm." },
    { q: "Reaksi A → B memiliki $\\Delta H = -120$ kJ. Nilai $\\Delta H$ untuk reaksi $2\\text{B} \\to 2\\text{A}$ adalah ...", options: ["$-240$ kJ", "$+240$ kJ", "$-120$ kJ", "$+120$ kJ"], answer: 1, solution: "Langkah 1: reaksi dibalik, maka tanda $\\Delta H$ berubah: B → A memiliki $\\Delta H = +120$ kJ. Langkah 2: koefisien dikali $2$, maka $\\Delta H$ ikut dikali $2$. Langkah 3: $\\Delta H = 2 \\times (+120) = +240$ kJ." },
    { q: "Faktor berikut dapat mempercepat laju reaksi, KECUALI ...", options: ["menaikkan suhu", "memperkecil ukuran partikel", "menurunkan konsentrasi pereaksi", "menambahkan katalis"], answer: 2, solution: "Langkah 1: laju reaksi bertambah jika tumbukan efektif antarpartikel bertambah. Langkah 2: menaikkan suhu, memperkecil ukuran partikel, dan menambah katalis semuanya memperbanyak tumbukan efektif. Langkah 3: menurunkan konsentrasi justru mengurangi tumbukan, sehingga memperlambat reaksi." },
    { q: "Pada saat sistem mencapai kesetimbangan kimia, yang terjadi adalah ...", options: ["reaksi berhenti total", "laju reaksi maju sama dengan laju reaksi balik", "konsentrasi pereaksi menjadi nol", "hanya reaksi maju yang berlangsung"], answer: 1, solution: "Langkah 1: kesetimbangan bersifat dinamis, artinya reaksi tetap berlangsung dua arah. Langkah 2: pada kesetimbangan, laju reaksi pembentukan produk sama dengan laju reaksi penguraiannya. Langkah 3: jadi laju reaksi maju = laju reaksi balik." },
    { q: "Atom $^{12}_{6}$C dan $^{14}_{6}$C saling berpasangan sebagai ...", options: ["isoton", "isotop", "isobar", "isoelektron"], answer: 1, solution: "Langkah 1: kedua atom memiliki nomor atom sama ($6$) tetapi nomor massa berbeda ($12$ dan $14$). Langkah 2: atom-atom dengan nomor atom sama tetapi nomor massa berbeda disebut isotop. Langkah 3: jadi keduanya merupakan isotop." },
    { q: "Dalam satu golongan sistem periodik dari atas ke bawah, jari-jari atom cenderung ...", options: ["bertambah", "berkurang", "tetap", "berubah tidak beraturan"], answer: 0, solution: "Langkah 1: dari atas ke bawah dalam satu golongan, jumlah kulit elektron bertambah. Langkah 2: kulit yang bertambah membuat ukuran atom semakin besar. Langkah 3: jadi jari-jari atom cenderung bertambah." },
    { q: "Larutan berikut yang dapat menghantarkan arus listrik paling baik adalah ...", options: ["larutan gula", "larutan urea", "larutan NaCl", "alkohol"], answer: 2, solution: "Langkah 1: larutan menghantarkan listrik jika mengandung ion-ion yang bergerak bebas. Langkah 2: gula, urea, dan alkohol tidak terionisasi dalam air (nonelektrolit). Langkah 3: NaCl terionisasi sempurna menjadi Na⁺ dan Cl⁻, jadi larutan NaCl menghantarkan listrik paling baik." },
    { q: "Bilangan oksidasi Mn dalam KMnO₄ adalah ...", options: ["$+4$", "$+7$", "$+5$", "$+2$"], answer: 1, solution: "Langkah 1: aturan biloks, K $= +1$ dan O $= -2$. Langkah 2: misalkan biloks Mn $= x$, maka $(+1) + x + 4(-2) = 0$. Langkah 3: $1 + x - 8 = 0$, sehingga $x = +7$." },
    { q: "Sistem koloid yang fase terdispersinya berupa zat padat dan medium pendispersinya berupa zat cair disebut ...", options: ["emulsi", "sol", "buih", "aerosol"], answer: 1, solution: "Langkah 1: koloid dibedakan berdasarkan wujud fase terdispersi dan medium pendispersi. Langkah 2: emulsi = cair dalam cair, buih = gas dalam cair, aerosol = padat/cair dalam gas. Langkah 3: padat dalam cair disebut sol, contohnya sol emas dan tinta." },
    { q: "Sifat koloid yang dapat digunakan untuk membedakan koloid dari larutan sejati adalah ...", options: ["gerak Brown", "adsorpsi", "dialisis", "efek Tyndall"], answer: 3, solution: "Langkah 1: larutan sejati meneruskan cahaya tanpa menghamburkannya. Langkah 2: partikel koloid berukuran cukup besar untuk menghamburkan berkas cahaya. Langkah 3: penghamburan cahaya oleh partikel koloid ini disebut efek Tyndall." },
    { q: "Gerak Brown pada sistem koloid disebabkan oleh ...", options: ["tumbukan antara molekul medium pendispersi dengan partikel koloid", "penyerapan muatan listrik oleh partikel koloid", "gaya gravitasi pada partikel koloid", "reaksi kimia dalam medium pendispersi"], answer: 0, solution: "Langkah 1: gerak Brown adalah gerak acak (zig-zag) partikel koloid. Langkah 2: molekul medium pendispersi bergerak terus-menerus dan menumbuk partikel koloid dari segala arah. Langkah 3: tumbukan yang tidak seimbang inilah yang membuat partikel koloid bergerak zig-zag." },
    { q: "Pada penjernihan air, penambahan tawas bertujuan untuk ...", options: ["membunuh bakteri patogen", "menaikkan pH air", "mengkoagulasikan partikel-partikel koloid lumpur", "menghilangkan bau air"], answer: 2, solution: "Langkah 1: air keruh mengandung partikel lumpur berukuran koloid yang sukar mengendap. Langkah 2: tawas (aluminium sulfat) menetralkan muatan partikel koloid sehingga terjadi koagulasi (penggumpalan). Langkah 3: gumpalan yang terbentuk menjadi besar dan mudah diendapkan atau disaring." },
    { q: "Sol Fe(OH)₃ dapat dibuat dengan cara kondensasi melalui reaksi ...", options: ["melarutkan serbuk Fe(OH)₃ dalam air dingin", "hidrolisis, yaitu meneteskan FeCl₃ jenuh ke dalam air mendidih", "menggerus padatan Fe(OH)₃ hingga halus", "memanaskan larutan Fe(OH)₃ pekat"], answer: 1, solution: "Langkah 1: cara kondensasi menggabungkan partikel kecil (ion/molekul) menjadi partikel berukuran koloid. Langkah 2: FeCl₃ yang diteteskan ke air mendidih terhidrolisis membentuk Fe(OH)₃. Langkah 3: partikel Fe(OH)₃ yang terbentuk berukuran koloid sehingga diperoleh sol Fe(OH)₃ berwarna merah kecokelatan." },
    { q: "Cara busur Bredig untuk membuat sol logam (misalnya sol emas) dilakukan dengan ...", options: ["melarutkan logam dalam asam kuat", "menggerus logam hingga menjadi serbuk halus", "memanaskan logam hingga meleleh", "melompatkan bunga api listrik di antara dua elektrode logam di dalam air"], answer: 3, solution: "Langkah 1: busur Bredig adalah cara dispersi, yaitu memecah partikel besar menjadi partikel berukuran koloid. Langkah 2: bunga api listrik dilewatkan di antara dua kawat elektrode logam yang tercelup dalam air. Langkah 3: logam menguap lalu mengembun di dalam air sebagai partikel berukuran koloid (sol logam)." },
    { q: "Susu dan santan merupakan contoh koloid jenis ...", options: ["sol", "emulsi", "aerosol", "gel"], answer: 1, solution: "Langkah 1: susu tersusun dari tetesan lemak/minyak yang terdispersi dalam air. Langkah 2: fase terdispersi (lemak) berwujud cair dan medium pendispersi (air) juga berwujud cair. Langkah 3: sistem koloid cair dalam cair disebut emulsi." },
    { q: "Contoh koloid jenis aerosol cair adalah ...", options: ["asap", "agar-agar", "kabut", "santan"], answer: 2, solution: "Langkah 1: aerosol adalah koloid dengan medium pendispersi berupa gas. Langkah 2: kabut tersusun dari tetesan air (cair) yang terdispersi di udara (gas). Langkah 3: jadi kabut adalah aerosol cair. (Asap = aerosol padat, agar-agar = gel, santan = emulsi.)" },
    { q: "Polimer yang terbentuk dari penggabungan monomer-monomer berikatan rangkap tanpa menghasilkan molekul kecil disebut polimer ...", options: ["adisi", "kondensasi", "kopolimer", "homopolimer"], answer: 0, solution: "Langkah 1: pada polimerisasi adisi, ikatan rangkap monomer terbuka lalu monomer-monomer bergabung satu per satu. Langkah 2: tidak ada molekul kecil (seperti H₂O) yang dilepaskan selama penggabungan. Langkah 3: jadi polimer tersebut tergolong polimer adisi, contohnya polietilena dan PVC." },
    { q: "Pasangan polimer dan monomer pembentuknya yang tepat untuk polimer adisi adalah ...", options: ["nilon-66 – asam adipat", "bakelit – fenol", "dakron – asam tereftalat", "polietilena – etena"], answer: 3, solution: "Langkah 1: polimer adisi berasal dari monomer yang berikatan rangkap. Langkah 2: etena (CH₂=CH₂) berikatan rangkap dan berpolimerisasi adisi menjadi polietilena. Langkah 3: nilon-66, bakelit, dan dakron justru terbentuk melalui polimerisasi kondensasi." },
    { q: "Nilon-66 dibuat melalui polimerisasi kondensasi dari monomer ...", options: ["asam adipat dan heksametilendiamina", "fenol dan formaldehida", "etena dan propena", "vinil klorida"], answer: 0, solution: "Langkah 1: nilon-66 adalah poliamida hasil polimerisasi kondensasi. Langkah 2: monomernya adalah asam dikarboksilat (asam adipat) dan diamina (heksametilendiamina). Langkah 3: keduanya bereaksi membentuk ikatan amida sambil melepaskan molekul air." },
    { q: "Bakelit, plastik termoset yang tahan panas, dibuat dari ...", options: ["etena dan oksigen", "stirena", "fenol dan formaldehida", "tetrafluoroetilena"], answer: 2, solution: "Langkah 1: bakelit termasuk polimer kondensasi jenis termoset. Langkah 2: monomernya adalah fenol dan formaldehida. Langkah 3: keduanya berkondensasi membentuk jaringan tiga dimensi yang keras dan tahan panas (dipakai untuk gagang alat masak dan colokan listrik)." },
    { q: "Uji biuret digunakan untuk mengidentifikasi protein. Hasil positif ditunjukkan oleh terbentuknya warna ...", options: ["merah bata", "ungu (violet)", "biru tua", "kuning"], answer: 1, solution: "Langkah 1: pereaksi biuret adalah larutan CuSO₄ dalam suasana basa (NaOH). Langkah 2: ion Cu²⁺ membentuk kompleks dengan ikatan peptida pada protein. Langkah 3: kompleks tersebut berwarna ungu (violet), sehingga warna ungu menandakan adanya protein." },
    { q: "Larutan glukosa dipanaskan dengan pereaksi Benedict. Hasil positif ditunjukkan oleh ...", options: ["timbulnya warna ungu", "timbulnya warna biru", "terbentuknya endapan merah bata", "terbentuknya endapan putih"], answer: 2, solution: "Langkah 1: pereaksi Benedict mengandung ion Cu²⁺ yang berwarna biru. Langkah 2: gula pereduksi seperti glukosa mereduksi Cu²⁺ menjadi Cu⁺ saat dipanaskan. Langkah 3: Cu⁺ mengendap sebagai Cu₂O berwarna merah bata, jadi endapan merah bata menandakan gula pereduksi." },
    { q: "Untuk menguji adanya amilum, bahan ditetesi larutan iodin. Hasil positif ditunjukkan oleh warna ...", options: ["merah bata", "biru kehitaman", "ungu", "kuning"], answer: 1, solution: "Langkah 1: iodin bereaksi dengan amilum membentuk kompleks. Langkah 2: molekul iodin terperangkap dalam struktur heliks amilosa penyusun amilum. Langkah 3: kompleks iodin-amilum berwarna biru kehitaman, sehingga warna tersebut menandakan adanya amilum." },
    { q: "Uji sederhana untuk mengidentifikasi lemak adalah meneteskan bahan pada kertas saring. Hasil positif ditunjukkan oleh ...", options: ["kertas berubah menjadi biru", "timbul gelembung gas", "kertas berubah menjadi merah", "kertas menjadi transparan (tembus cahaya)"], answer: 3, solution: "Langkah 1: lemak tidak larut dalam air tetapi meninggalkan noda minyak pada kertas. Langkah 2: noda minyak membuat serat kertas menjadi tembus cahaya. Langkah 3: jadi kertas yang menjadi transparan menandakan bahan mengandung lemak." },
    { q: "Hujan asam terutama disebabkan oleh gas ...", options: ["CO₂ dan O₂", "N₂ dan H₂", "SO₂ dan NO₂", "O₂ dan He"], answer: 2, solution: "Langkah 1: gas SO₂ dan NO₂ dari pembakaran bahan bakar fosil dan kendaraan naik ke atmosfer. Langkah 2: keduanya bereaksi dengan uap air membentuk H₂SO₄ dan HNO₃. Langkah 3: air hujan yang mengandung asam-asam ini memiliki pH di bawah 5,6 dan disebut hujan asam." },
    { q: "Berikut ini yang BUKAN gas rumah kaca adalah ...", options: ["CO₂", "O₂", "CH₄", "N₂O"], answer: 1, solution: "Langkah 1: gas rumah kaca menyerap radiasi inframerah dari bumi sehingga panas terperangkap di atmosfer. Langkah 2: CO₂, CH₄ (metana), dan N₂O (dinitrogen oksida) termasuk gas rumah kaca. Langkah 3: O₂ tidak menyerap radiasi inframerah secara signifikan, jadi O₂ bukan gas rumah kaca." },
    { q: "BOD (Biochemical Oxygen Demand) pada air limbah menunjukkan ...", options: ["jumlah oksigen yang dibutuhkan mikroorganisme untuk menguraikan zat organik", "jumlah maksimum oksigen yang dapat larut dalam air", "kadar karbon dioksida dalam air", "tingkat keasaman air limbah"], answer: 0, solution: "Langkah 1: BOD mengukur kebutuhan oksigen oleh aktivitas biologis di perairan. Langkah 2: mikroorganisme pengurai memerlukan oksigen untuk menguraikan zat organik dalam limbah. Langkah 3: semakin tinggi nilai BOD, semakin tercemar air tersebut oleh bahan organik." },
    { q: "Eutrofikasi pada perairan adalah peristiwa ...", options: ["penurunan pH air akibat hujan asam", "pengendapan logam berat di dasar perairan", "pengkayaan nutrien berlebih yang memicu ledakan pertumbuhan alga", "penguapan air danau secara berlebihan"], answer: 2, solution: "Langkah 1: limbah deterjen dan pupuk mengandung fosfat dan nitrat yang masuk ke perairan. Langkah 2: nutrien berlebih memicu pertumbuhan alga yang sangat cepat (blooming). Langkah 3: peristiwa pengkayaan nutrien ini disebut eutrofikasi, yang akhirnya menurunkan kadar oksigen terlarut." },
{ q: "Menurut model atom Thomson, atom digambarkan sebagai ...", options: ["bola pejal kecil yang tidak dapat dibagi lagi", "inti kecil bermuatan positif yang dikelilingi elektron", "awan kebolehjadian menemukan elektron di sekitar inti", "bola bermuatan positif dengan elektron tersebar di dalamnya seperti roti kismis"], answer: 3, solution: "1. Model atom Thomson dikenal dengan sebutan model roti kismis. 2. Menurut Thomson, atom berbentuk bola bermuatan positif dengan elektron-elektron bermuatan negatif tersebar di dalamnya. 3. Jadi jawabannya adalah bola bermuatan positif dengan elektron tersebar seperti roti kismis." },
{ q: "Pada percobaan hamburan partikel alfa oleh Rutherford, sebagian kecil partikel alfa dipantulkan kembali. Fakta ini membuktikan bahwa ...", options: ["elektron tersebar merata di seluruh bagian atom", "atom memiliki inti yang kecil, padat, dan bermuatan positif", "atom sebagian besar berupa ruang hampa tanpa inti", "seluruh massa atom terpusat pada elektron"], answer: 1, solution: "1. Sebagian besar partikel alfa diteruskan menembus lempeng emas, artinya atom sebagian besar berupa ruang kosong. 2. Sebagian kecil partikel alfa dibelokkan atau dipantulkan karena menabrak sesuatu yang sangat kecil, padat, dan bermuatan positif. 3. Jadi atom memiliki inti yang kecil, padat, dan bermuatan positif." },
{ q: "Menurut model atom Bohr, elektron ...", options: ["mengelilingi inti pada lintasan tertentu dengan tingkat energi tertentu", "tersebar merata dalam bola bermuatan positif", "bergerak bebas tanpa lintasan yang jelas", "diam tidak bergerak di dalam inti atom"], answer: 0, solution: "1. Bohr menyempurnakan model Rutherford dengan gagasan kuantisasi energi. 2. Elektron hanya dapat menempati lintasan-lintasan (kulit) dengan tingkat energi tertentu, tidak sembarang. 3. Jadi elektron mengelilingi inti pada lintasan tertentu dengan tingkat energi tertentu." },
{ q: "Dalam model atom mekanika kuantum, keberadaan elektron di sekitar inti dinyatakan sebagai ...", options: ["titik pasti pada lintasan lingkaran", "partikel yang diam pada kulit atom", "kebolehjadian menemukan elektron dalam suatu orbital", "gelombang yang terperangkap di dalam inti"], answer: 2, solution: "1. Model mekanika kuantum dikembangkan dari asas ketidakpastian Heisenberg dan persamaan Schrödinger. 2. Posisi pasti elektron tidak dapat ditentukan, yang dapat diketahui hanyalah kebolehjadian (probabilitas) menemukannya pada suatu daerah yang disebut orbital. 3. Jadi keberadaan elektron dinyatakan sebagai kebolehjadian menemukan elektron dalam suatu orbital." },
{ q: "Partikel subatom yang ditemukan oleh Chadwick dan tidak bermuatan listrik adalah ...", options: ["elektron", "proton", "foton", "neutron"], answer: 3, solution: "1. Chadwick menemukan partikel netral yang terletak di inti atom. 2. Partikel tersebut tidak bermuatan listrik dan massanya hampir sama dengan massa proton. 3. Partikel tersebut adalah neutron." },
{ q: "Suatu atom memiliki 15 proton, 16 neutron, dan 15 elektron. Nomor massa atom tersebut adalah ...", options: ["15", "31", "30", "16"], answer: 1, solution: "1. Diketahui jumlah proton = 15 dan jumlah neutron = 16. 2. Gunakan rumus nomor massa $A$ = jumlah proton + jumlah neutron $= 15 + 16$. 3. Jadi nomor massanya adalah 31." },
{ q: "Atom $^{31}_{15}$P dan $^{32}_{16}$S sama-sama memiliki 16 neutron. Pasangan atom seperti ini disebut ...", options: ["isoton", "isotop", "isobar", "isoelektron"], answer: 0, solution: "1. Jumlah neutron P $= 31 - 15 = 16$ dan jumlah neutron S $= 32 - 16 = 16$. 2. Atom-atom dengan jumlah neutron sama tetapi nomor atom berbeda disebut isoton. 3. Jadi pasangan tersebut merupakan isoton." },
{ q: "Pasangan atom yang memiliki nomor massa sama tetapi nomor atom berbeda disebut ...", options: ["isotop", "isomer", "isobar", "isoton"], answer: 2, solution: "1. Isotop = nomor atom sama tetapi nomor massa berbeda, sedangkan isoton = jumlah neutron sama. 2. Pasangan dengan nomor massa (jumlah proton + neutron) sama tetapi nomor atom berbeda disebut isobar, contohnya $^{40}_{18}$Ar dan $^{40}_{20}$Ca. 3. Jadi jawabannya adalah isobar." },
{ q: "Unsur klor (nomor atom 17) memiliki konfigurasi elektron 2, 8, 7. Jumlah elektron valensi unsur tersebut adalah ...", options: ["2", "8", "17", "7"], answer: 3, solution: "1. Elektron valensi adalah elektron pada kulit terluar. 2. Pada konfigurasi 2, 8, 7, kulit terluar (kulit M) berisi 7 elektron. 3. Jadi jumlah elektron valensinya adalah 7." },
{ q: "Unsur kalsium (nomor atom 20) terletak pada golongan ...", options: ["IA", "IIA", "VIA", "VIIIA"], answer: 1, solution: "1. Konfigurasi elektron Ca (20) adalah 2, 8, 8, 2. 2. Golongan ditentukan oleh jumlah elektron valensi, yaitu elektron pada kulit terluar = 2. 3. Unsur dengan 2 elektron valensi terletak pada golongan IIA." },
{ q: "Himpunan bilangan kuantum yang tepat untuk elektron pada subkulit 4d adalah ...", options: ["n = 4, l = 2", "n = 4, l = 3", "n = 3, l = 2", "n = 4, l = 1"], answer: 0, solution: "1. Bilangan kuantum utama (n) menyatakan kulit: subkulit 4d berarti n = 4. 2. Bilangan kuantum azimut (l) menyatakan jenis subkulit: s = 0, p = 1, d = 2, f = 3, jadi untuk subkulit d, l = 2. 3. Jadi himpunan yang tepat adalah n = 4, l = 2." },
{ q: "Bilangan kuantum azimut l = 2 menunjukkan elektron berada pada subkulit ...", options: ["s", "p", "d", "f"], answer: 2, solution: "1. Bilangan kuantum azimut menyatakan bentuk subkulit. 2. Nilai l = 0 untuk subkulit s, l = 1 untuk p, l = 2 untuk d, dan l = 3 untuk f. 3. Jadi l = 2 berarti subkulit d." },
{ q: "Jumlah orbital maksimum pada subkulit d adalah ...", options: ["1", "3", "7", "5"], answer: 3, solution: "1. Diketahui subkulit d memiliki bilangan kuantum azimut l = 2. 2. Gunakan rumus jumlah orbital $= 2l + 1 = 2(2) + 1 = 5$. 3. Jadi jumlah orbital maksimum pada subkulit d adalah 5." },
{ q: "Jumlah maksimum elektron yang dapat menempati kulit M (n = 3) adalah ...", options: ["8", "18", "32", "2"], answer: 1, solution: "1. Diketahui bilangan kuantum utama kulit M adalah n = 3. 2. Gunakan rumus jumlah elektron maksimum $= 2n^2 = 2(3)^2 = 18$. 3. Jadi kulit M dapat menampung maksimum 18 elektron." },
{ q: "Menurut aturan Hund, pengisian elektron pada orbital-orbital yang setingkat energi (degenerate) dilakukan dengan ...", options: ["mengisi tiap orbital dengan satu elektron berspin paralel terlebih dahulu", "memasangkan dua elektron dalam satu orbital terlebih dahulu", "mengisi mulai dari orbital dengan energi tertinggi", "menempatkan elektron hanya pada satu orbital"], answer: 0, solution: "1. Aturan Hund mengatur pengisian orbital-orbital bertingkat energi sama, misalnya tiga orbital p. 2. Elektron-elektron mengisi masing-masing orbital satu per satu dengan arah spin yang sama (paralel) sebelum ada yang berpasangan. 3. Jadi tiap orbital diisi satu elektron berspin paralel terlebih dahulu." },
{ q: "Konfigurasi elektron unsur kromium (nomor atom 24) yang tepat adalah ...", options: ["[Ar] 4s² 3d⁴", "[Ar] 4s¹ 3d⁶", "[Ar] 4s¹ 3d⁵", "[Ar] 4s² 3d⁵"], answer: 2, solution: "1. Menurut asas Aufbau, konfigurasi yang diperkirakan adalah [Ar] 4s² 3d⁴. 2. Namun subkulit d yang terisi setengah penuh (d⁵) lebih stabil, sehingga satu elektron dari 4s pindah ke 3d. 3. Jadi konfigurasi yang tepat adalah [Ar] 4s¹ 3d⁵." },
{ q: "Konfigurasi elektron ion Fe²⁺ (nomor atom Fe = 26) adalah ...", options: ["[Ar] 4s² 3d⁴", "[Ar] 4s¹ 3d⁵", "[Ar] 4s² 3d⁶", "[Ar] 3d⁶"], answer: 3, solution: "1. Konfigurasi atom Fe (26) adalah [Ar] 4s² 3d⁶. 2. Saat membentuk ion positif, elektron dilepaskan terlebih dahulu dari subkulit dengan n terbesar, yaitu 4s. 3. Fe melepaskan 2 elektron dari 4s, sehingga Fe²⁺ = [Ar] 3d⁶." },
{ q: "Dalam satu periode dari kiri ke kanan, energi ionisasi unsur-unsur cenderung ...", options: ["berkurang", "bertambah", "tetap", "berubah tidak beraturan"], answer: 1, solution: "1. Dari kiri ke kanan dalam satu periode, jumlah proton (muatan inti) bertambah sedangkan jumlah kulit tetap. 2. Muatan inti efektif yang lebih besar menarik elektron terluar lebih kuat sehingga jari-jari mengecil. 3. Elektron semakin sukar dilepas, jadi energi ionisasi cenderung bertambah." },
{ q: "Unsur yang memiliki keelektronegatifan terbesar adalah ...", options: ["fluorin", "oksigen", "klorin", "natrium"], answer: 0, solution: "1. Keelektronegatifan adalah kecenderungan atom menarik pasangan elektron ikatan. 2. Dalam sistem periodik, keelektronegatifan bertambah dari kiri ke kanan dan dari bawah ke atas. 3. Fluorin terletak paling kanan-atas (golongan VIIA periode 2), sehingga keelektronegatifannya terbesar." },
{ q: "Dalam satu periode dari kiri ke kanan, jari-jari atom cenderung ...", options: ["bertambah", "tetap", "berkurang", "berubah tidak beraturan"], answer: 2, solution: "1. Dari kiri ke kanan dalam satu periode, jumlah proton dalam inti bertambah. 2. Gaya tarik inti terhadap elektron kulit terluar semakin kuat. 3. Akibatnya ukuran atom menyusut, jadi jari-jari atom cenderung berkurang." },
{ q: "Urutan jari-jari atom yang tepat untuk unsur-unsur periode 3 berikut adalah ...", options: ["Al > Mg > Na", "Mg > Al > Na", "Na > Al > Mg", "Na > Mg > Al"], answer: 3, solution: "1. Na, Mg, dan Al terletak pada periode 3 dengan urutan golongan IA, IIA, IIIA. 2. Dalam satu periode, jari-jari atom berkurang dari kiri ke kanan. 3. Jadi urutannya adalah Na > Mg > Al." },
{ q: "Unsur yang memiliki afinitas elektron terbesar adalah ...", options: ["fluorin", "klorin", "oksigen", "bromin"], answer: 1, solution: "1. Afinitas elektron adalah energi yang dilepaskan saat atom menangkap elektron. 2. Unsur golongan halogen (VIIA) memiliki afinitas elektron besar karena hampir mencapai konfigurasi oktet. 3. Klorin memiliki afinitas elektron terbesar, sedikit lebih besar daripada fluorin karena ukuran atom fluorin yang sangat kecil menimbulkan tolakan antarelektron." },
{ q: "Pasangan ion berikut yang isoelektronik (memiliki jumlah elektron sama) adalah ...", options: ["Na⁺ dan Mg²⁺", "Na⁺ dan K⁺", "Mg²⁺ dan Ca²⁺", "F⁻ dan Cl⁻"], answer: 0, solution: "1. Hitung jumlah elektron tiap ion: Na (11) melepas 1 elektron menjadi Na⁺ = 10 elektron. 2. Mg (12) melepas 2 elektron menjadi Mg²⁺ = 10 elektron. 3. Keduanya memiliki 10 elektron (seperti neon), jadi Na⁺ dan Mg²⁺ isoelektronik." },
{ q: "Unsur periode 3 yang terletak pada golongan VIA adalah ...", options: ["fosfor", "aluminium", "belerang", "klorin"], answer: 2, solution: "1. Golongan VIA berarti memiliki 6 elektron valensi. 2. Unsur periode 3 dengan 6 elektron valensi memiliki nomor atom 16 dengan konfigurasi 2, 8, 6. 3. Unsur tersebut adalah belerang (S)." },
{ q: "Pada ion amonium (NH₄⁺), ikatan antara atom N dengan atom H yang keempat merupakan ikatan ...", options: ["ion", "kovalen biasa", "logam", "kovalen koordinasi"], answer: 3, solution: "1. Molekul NH₃ memiliki satu pasangan elektron bebas pada atom N. 2. Ion H⁺ (tanpa elektron) memakai pasangan elektron bebas milik N untuk berikatan, sehingga kedua elektron ikatan berasal dari atom N saja. 3. Ikatan kovalen yang kedua elektronnya berasal dari satu atom disebut ikatan kovalen koordinasi." },
{ q: "Contoh spesi yang mengandung ikatan kovalen koordinasi adalah ...", options: ["NaCl", "H₃O⁺", "CH₄", "MgO"], answer: 1, solution: "1. Ikatan kovalen koordinasi terjadi bila pasangan elektron ikatan berasal dari satu atom saja. 2. Ion hidronium (H₃O⁺) terbentuk dari H₂O yang menyumbangkan pasangan elektron bebas atom O kepada ion H⁺. 3. Jadi H₃O⁺ mengandung ikatan kovalen koordinasi." },
{ q: "Ikatan logam dapat digambarkan sebagai ...", options: ["kation-kation logam yang tersusun teratur dalam lautan elektron valensi yang bergerak bebas", "serah terima elektron antara atom logam dan nonlogam", "pemakaian bersama pasangan elektron oleh dua atom nonlogam", "gaya tarik-menarik antara molekul-molekul netral"], answer: 0, solution: "1. Pada logam, elektron valensi tidak terikat pada atom tertentu melainkan terdelokalisasi. 2. Kation-kation logam tersusun dalam kisi kristal yang dikelilingi lautan elektron bebas. 3. Jadi ikatan logam adalah kation-kation logam dalam lautan elektron valensi yang bergerak bebas." },
{ q: "Gaya antarmolekul yang bekerja pada molekul nonpolar seperti Cl₂ adalah gaya ...", options: ["ikatan hidrogen", "gaya dipol-dipol", "gaya London (gaya dispersi)", "gaya ion-dipol"], answer: 2, solution: "1. Cl₂ adalah molekul nonpolar sehingga tidak memiliki dipol permanen. 2. Gerakan elektron yang acak menimbulkan dipol sesaat yang mengimbas dipol pada molekul tetangga. 3. Gaya tarik akibat dipol sesaat terimbas ini disebut gaya London (gaya dispersi)." },
{ q: "Di antara senyawa berikut, yang molekul-molekulnya dapat membentuk ikatan hidrogen adalah ...", options: ["CH₄", "HCl", "CO₂", "H₂O"], answer: 3, solution: "1. Ikatan hidrogen terjadi antara atom H yang terikat pada atom sangat elektronegatif (N, O, atau F) dengan pasangan elektron bebas atom N, O, atau F pada molekul lain. 2. Pada H₂O, atom H terikat langsung pada O yang sangat elektronegatif. 3. Jadi molekul H₂O dapat membentuk ikatan hidrogen." },
{ q: "Titik didih HF jauh lebih tinggi daripada HCl, padahal massa molekul HF lebih kecil. Hal ini disebabkan oleh ...", options: ["massa molekul HF yang lebih besar", "adanya ikatan hidrogen antarmolekul HF", "HF berikatan ion", "HCl bersifat nonpolar"], answer: 1, solution: "1. Jika hanya dipengaruhi massa molekul (gaya London), titik didih HCl (M_r = 36,5) seharusnya lebih tinggi daripada HF (M_r = 20). 2. Kenyataannya HF jauh lebih tinggi karena antarmolekul HF terdapat ikatan hidrogen yang jauh lebih kuat daripada gaya London. 3. Jadi tingginya titik didih HF disebabkan oleh ikatan hidrogen." },
{ q: "Bentuk molekul BeCl₂ menurut teori VSEPR adalah ...", options: ["linear", "bengkok", "segitiga planar", "tetrahedral"], answer: 0, solution: "1. Atom pusat Be memiliki 2 pasangan elektron ikatan dan 0 pasangan elektron bebas (tipe AX₂). 2. Dua domain elektron akan saling menjauh membentuk sudut 180° agar tolakan minimum. 3. Jadi bentuk molekul BeCl₂ adalah linear." },
{ q: "Bentuk molekul BF₃ adalah ...", options: ["linear", "piramida trigonal", "segitiga planar", "bengkok"], answer: 2, solution: "1. Atom pusat B memiliki 3 pasangan elektron ikatan dan 0 pasangan elektron bebas (tipe AX₃). 2. Tiga domain elektron tersusun dengan sudut 120° pada satu bidang datar. 3. Jadi bentuk molekul BF₃ adalah segitiga planar." },
{ q: "Bentuk molekul CH₄ adalah ...", options: ["segitiga planar", "bengkok", "linear", "tetrahedral"], answer: 3, solution: "1. Atom pusat C memiliki 4 pasangan elektron ikatan dan 0 pasangan elektron bebas (tipe AX₄). 2. Empat domain elektron tersusun menuju sudut-sudut tetrahedron dengan sudut ikatan 109,5°. 3. Jadi bentuk molekul CH₄ adalah tetrahedral." },
{ q: "Bentuk molekul NH₃ adalah ...", options: ["tetrahedral", "piramida trigonal", "bengkok", "segitiga planar"], answer: 1, solution: "1. Atom pusat N memiliki 3 pasangan elektron ikatan dan 1 pasangan elektron bebas (tipe AX₃E). 2. Pasangan elektron bebas menekan tiga ikatan N–H ke bawah membentuk bangun seperti piramida. 3. Jadi bentuk molekul NH₃ adalah piramida trigonal." },
{ q: "Bentuk molekul H₂O adalah ...", options: ["bengkok (seperti huruf V)", "linear", "piramida trigonal", "tetrahedral"], answer: 0, solution: "1. Atom pusat O memiliki 2 pasangan elektron ikatan dan 2 pasangan elektron bebas (tipe AX₂E₂). 2. Dua pasangan elektron bebas menekan dua ikatan O–H sehingga sudutnya mengecil menjadi sekitar 104,5°. 3. Jadi bentuk molekul H₂O adalah bengkok (seperti huruf V)." },
{ q: "Di antara molekul berikut, yang bersifat nonpolar adalah ...", options: ["H₂O", "NH₃", "CO₂", "HCl"], answer: 2, solution: "1. Kepolaran molekul ditentukan oleh resultan momen dipol seluruh ikatannya. 2. CO₂ berbentuk linear dan simetris, sehingga dua momen dipol ikatan C=O saling meniadakan (resultan nol). 3. Jadi CO₂ bersifat nonpolar." },
{ q: "Molekul CCl₄ bersifat nonpolar sedangkan CHCl₃ bersifat polar. Hal ini karena ...", options: ["CCl₄ berikatan ion", "ikatan C–Cl bersifat nonpolar", "CHCl₃ memiliki ikatan hidrogen", "CCl₄ berbentuk tetrahedral yang simetris sehingga momen dipolnya saling meniadakan"], answer: 3, solution: "1. Kedua molekul sama-sama memiliki ikatan C–Cl yang polar. 2. Pada CCl₄, empat ikatan tersusun tetrahedral simetris sehingga resultan momen dipolnya nol. 3. Pada CHCl₃, penggantian satu Cl oleh H merusak kesimetrisan sehingga resultannya tidak nol dan molekul menjadi polar." },
{ q: "Ikatan ion dalam MgO terbentuk karena ...", options: ["pemakaian elektron bersama antara Mg dan O", "atom Mg melepaskan 2 elektron yang kemudian ditangkap oleh atom O", "atom O melepaskan elektronnya kepada atom Mg", "adanya gaya London antara Mg dan O"], answer: 1, solution: "1. Mg (golongan IIA) cenderung melepaskan 2 elektron valensinya membentuk Mg²⁺. 2. O (golongan VIA) cenderung menangkap 2 elektron membentuk O²⁻. 3. Serah terima elektron ini menghasilkan kation dan anion yang saling tarik secara elektrostatik, yaitu ikatan ion." },
{ q: "Senyawa ion dalam wujud padat tidak dapat menghantarkan listrik karena ...", options: ["ion-ionnya terkunci pada kisi kristal sehingga tidak dapat bergerak bebas", "tidak mengandung elektron sama sekali", "senyawa ion selalu berwujud gas", "ikatan ion sangat lemah sehingga mudah putus"], answer: 0, solution: "1. Arus listrik dalam larutan atau lelehan dihantarkan oleh ion-ion yang bergerak bebas. 2. Dalam wujud padat, ion-ion tersusun teratur dan terikat kuat pada kisi kristal. 3. Karena ion tidak dapat bergerak bebas, senyawa ion padat tidak menghantarkan listrik." },
{ q: "Ikatan pada molekul HCl tergolong kovalen polar karena ...", options: ["kedua atom penyusunnya sama-sama nonlogam", "terjadi serah terima elektron", "keelektronegatifan Cl lebih besar daripada H sehingga pasangan elektron tertarik ke arah Cl", "HCl mudah larut dalam air"], answer: 2, solution: "1. Ikatan kovalen polar terjadi bila pasangan elektron ikatan tertarik lebih kuat ke salah satu atom. 2. Keelektronegatifan Cl jauh lebih besar daripada H, sehingga kerapatan elektron bergeser ke arah Cl. 3. Pergeseran ini menimbulkan kutub parsial positif pada H dan negatif pada Cl." },
{ q: "Gaya antarmolekul utama yang bekerja pada zat polar seperti HCl adalah ...", options: ["gaya London", "ikatan hidrogen", "gaya ion-dipol", "gaya dipol-dipol"], answer: 3, solution: "1. HCl adalah molekul polar dengan ujung H bermuatan parsial positif dan ujung Cl bermuatan parsial negatif. 2. Ujung positif suatu molekul menarik ujung negatif molekul tetangga. 3. Gaya tarik antara dipol permanen ini disebut gaya dipol-dipol." },
{ q: "Jumlah pasangan elektron bebas (PEB) pada atom pusat molekul H₂O adalah ...", options: ["1", "2", "3", "4"], answer: 1, solution: "1. Atom O memiliki 6 elektron valensi. 2. Dua elektron dipakai untuk dua ikatan O–H, tersisa 4 elektron. 3. Empat elektron setara dengan 2 pasangan elektron bebas." },
{ q: "Molekul yang memiliki ikatan kovalen rangkap tiga adalah ...", options: ["N₂", "O₂", "H₂", "Cl₂"], answer: 0, solution: "1. Atom N memiliki 5 elektron valensi dan membutuhkan 3 elektron lagi untuk mencapai oktet. 2. Dua atom N memakai bersama 3 pasang elektron agar keduanya mencapai oktet. 3. Jadi N₂ memiliki ikatan kovalen rangkap tiga (N≡N)." },
{ q: "Jumlah total elektron valensi yang digambarkan pada struktur Lewis CO₂ adalah ...", options: ["8", "12", "16", "20"], answer: 2, solution: "1. Hitung elektron valensi tiap atom: C golongan IVA = 4, O golongan VIA = 6. 2. Total $= 4 + 2(6) = 16$ elektron valensi. 3. Jadi struktur Lewis CO₂ digambarkan dengan 16 elektron valensi." },
{ q: "Urutan gaya antarmolekul dari yang terlemah hingga terkuat adalah ...", options: ["ikatan hidrogen < dipol-dipol < London", "dipol-dipol < ikatan hidrogen < London", "London < ikatan hidrogen < dipol-dipol", "London < dipol-dipol < ikatan hidrogen"], answer: 3, solution: "1. Gaya London (dipol sesaat terimbas) adalah yang paling lemah dan terdapat pada semua molekul. 2. Gaya dipol-dipol (antar dipol permanen) lebih kuat daripada gaya London. 3. Ikatan hidrogen adalah jenis khusus gaya dipol-dipol yang paling kuat, jadi urutannya London < dipol-dipol < ikatan hidrogen." },
{ q: "Jumlah pasangan elektron bebas (PEB) pada atom N dalam molekul NH₃ adalah ...", options: ["0", "1", "2", "3"], answer: 1, solution: "1. Atom N memiliki 5 elektron valensi. 2. Tiga elektron dipakai untuk tiga ikatan N–H, tersisa 2 elektron. 3. Dua elektron setara dengan 1 pasangan elektron bebas." },
{ q: "Pada penggambaran struktur Lewis molekul H₂O, jumlah total elektron valensi yang ditampilkan adalah ...", options: ["8", "10", "6", "12"], answer: 0, solution: "1. Hitung elektron valensi tiap atom: H golongan IA = 1, O golongan VIA = 6. 2. Total $= 2(1) + 6 = 8$ elektron valensi. 3. Jadi struktur Lewis H₂O digambarkan dengan 8 elektron valensi." },
{ q: "Jumlah pasangan elektron ikatan (PEI) pada molekul CH₄ adalah ...", options: ["2", "3", "4", "1"], answer: 2, solution: "1. Atom C mengikat 4 atom H, masing-masing dengan satu ikatan kovalen tunggal. 2. Setiap ikatan tunggal terdiri dari 1 pasangan elektron ikatan. 3. Jadi jumlah pasangan elektron ikatan pada CH₄ adalah 4." },
{ q: "Massa molekul relatif (M_r) CaCO₃ adalah ... (A_r: Ca = 40, C = 12, O = 16)", options: ["90", "110", "84", "100"], answer: 3, solution: "1. Diketahui A_r: Ca = 40, C = 12, O = 16. 2. Gunakan rumus $M_r = A_r\\ \\text{Ca} + A_r\\ \\text{C} + 3(A_r\\ \\text{O}) = 40 + 12 + 3(16)$. 3. $= 40 + 12 + 48 = 100$." },
{ q: "M_r glukosa (C₆H₁₂O₆) adalah ... (A_r: C = 12, H = 1, O = 16)", options: ["150", "180", "196", "162"], answer: 1, solution: "1. Diketahui A_r: C = 12, H = 1, O = 16. 2. $M_r = 6(12) + 12(1) + 6(16) = 72 + 12 + 96$. 3. $= 180$." },
{ q: "Jumlah mol dalam 8 gram NaOH adalah ... (M_r NaOH = 40)", options: ["0,2 mol", "0,4 mol", "0,02 mol", "2 mol"], answer: 0, solution: "1. Diketahui massa $= 8\\ \\text{g}$ dan $M_r = 40$. 2. Gunakan rumus $n = \\frac{\\text{massa}}{M_r} = \\frac{8}{40}$. 3. $n = 0{,}2\\ \\text{mol}$." },
{ q: "Massa 0,25 mol CaCO₃ adalah ... (M_r CaCO₃ = 100)", options: ["40 g", "4 g", "25 g", "2,5 g"], answer: 2, solution: "1. Diketahui $n = 0{,}25\\ \\text{mol}$ dan $M_r = 100$. 2. Gunakan rumus massa $= n \\times M_r = 0{,}25 \\times 100$. 3. Massa $= 25\\ \\text{g}$." },
{ q: "Jumlah partikel dalam 0,5 mol atom karbon adalah ...", options: ["6,02 × 10²²", "1,204 × 10²⁴", "3,01 × 10²²", "3,01 × 10²³"], answer: 3, solution: "1. Diketahui $n = 0{,}5\\ \\text{mol}$ dan bilangan Avogadro $= 6{,}02 \\times 10^{23}$. 2. Jumlah partikel $= n \\times 6{,}02 \\times 10^{23} = 0{,}5 \\times 6{,}02 \\times 10^{23}$. 3. $= 3{,}01 \\times 10^{23}$ partikel." },
{ q: "Volume 2 mol gas CO₂ pada keadaan STP adalah ...", options: ["11,2 L", "44,8 L", "22,4 L", "89,6 L"], answer: 1, solution: "1. Pada keadaan STP, volume 1 mol gas $= 22{,}4\\ \\text{L}$. 2. Volume $= n \\times 22{,}4 = 2 \\times 22{,}4$. 3. $= 44{,}8\\ \\text{L}$." },
{ q: "Suatu senyawa mengandung 40% massa C, 6,7% massa H, dan 53,3% massa O. Rumus empiris senyawa tersebut adalah ... (A_r: C = 12, H = 1, O = 16)", options: ["CH₂O", "C₂H₄O", "CHO", "CH₄O"], answer: 0, solution: "1. Misalkan massa senyawa 100 g, maka mol tiap unsur: C $= 40/12 = 3{,}33$; H $= 6{,}7/1 = 6{,}7$; O $= 53{,}3/16 = 3{,}33$. 2. Bagi dengan nilai terkecil (3,33): C : H : O $= 1 : 2 : 1$. 3. Jadi rumus empirisnya adalah CH₂O." },
{ q: "Rumus empiris suatu senyawa adalah CH₂O dengan M_r = 180. Rumus molekul senyawa tersebut adalah ...", options: ["C₂H₄O₂", "CH₂O", "C₆H₁₂O₆", "C₃H₆O₃"], answer: 2, solution: "1. Hitung M_r rumus empiris: CH₂O $= 12 + 2(1) + 16 = 30$. 2. Nilai $n = \\frac{M_r\\ \\text{senyawa}}{M_r\\ \\text{empiris}} = \\frac{180}{30} = 6$. 3. Rumus molekul $= (\\text{CH}_2\\text{O})_6 = \\text{C}_6\\text{H}_{12}\\text{O}_6$." },
{ q: "Sebanyak 4 mol H₂ direaksikan dengan 3 mol O₂ menurut reaksi 2H₂ + O₂ → 2H₂O. Jumlah mol H₂O yang terbentuk adalah ...", options: ["3 mol", "6 mol", "8 mol", "4 mol"], answer: 3, solution: "1. Perbandingan koefisien H₂ : O₂ = 2 : 1. Untuk 4 mol H₂ dibutuhkan $4/2 = 2$ mol O₂ (tersedia 3 mol), jadi H₂ habis lebih dulu (pereaksi pembatas). 2. Perbandingan H₂ : H₂O = 2 : 2, maka mol H₂O $= \\frac{2}{2} \\times 4 = 4$ mol. 3. Jadi H₂O yang terbentuk adalah 4 mol." },
{ q: "Sebanyak 10 gram H₂ direaksikan dengan 40 gram O₂ (2H₂ + O₂ → 2H₂O). Massa H₂O yang terbentuk adalah ... (M_r: H₂ = 2, O₂ = 32, H₂O = 18)", options: ["90 g", "45 g", "22,5 g", "36 g"], answer: 1, solution: "1. Hitung mol: $n(\\text{H}_2) = 10/2 = 5$ mol; $n(\\text{O}_2) = 40/32 = 1{,}25$ mol. 2. Untuk 1,25 mol O₂ dibutuhkan $2 \\times 1{,}25 = 2{,}5$ mol H₂ (tersedia 5 mol), jadi O₂ adalah pereaksi pembatas dan mol H₂O $= 2 \\times 1{,}25 = 2{,}5$ mol. 3. Massa H₂O $= 2{,}5 \\times 18 = 45\\ \\text{g}$." },
{ q: "Hasil teoritis suatu reaksi adalah 50 gram, sedangkan hasil nyata yang diperoleh 40 gram. Persen hasil reaksi tersebut adalah ...", options: ["80%", "125%", "75%", "90%"], answer: 0, solution: "1. Diketahui hasil teoritis = 50 g dan hasil nyata = 40 g. 2. Gunakan rumus persen hasil $= \\frac{\\text{hasil nyata}}{\\text{hasil teoritis}} \\times 100\\% = \\frac{40}{50} \\times 100\\%$. 3. $= 80\\%$." },
{ q: "Sebanyak 20 gram CaCO₃ dipanaskan menurut reaksi CaCO₃ → CaO + CO₂. Massa CO₂ yang terbentuk adalah ... (M_r: CaCO₃ = 100, CO₂ = 44)", options: ["4,4 g", "17,6 g", "8,8 g", "11,2 g"], answer: 2, solution: "1. $n(\\text{CaCO}_3) = 20/100 = 0{,}2$ mol. 2. Perbandingan koefisien CaCO₃ : CO₂ = 1 : 1, jadi $n(\\text{CO}_2) = 0{,}2$ mol. 3. Massa CO₂ $= 0{,}2 \\times 44 = 8{,}8\\ \\text{g}$." },
{ q: "Sebanyak 13 gram logam Zn direaksikan dengan HCl berlebih (Zn + 2HCl → ZnCl₂ + H₂). Volume gas H₂ yang dihasilkan pada STP adalah ... (A_r Zn = 65)", options: ["2,24 L", "11,2 L", "22,4 L", "4,48 L"], answer: 3, solution: "1. $n(\\text{Zn}) = 13/65 = 0{,}2$ mol. 2. Perbandingan Zn : H₂ = 1 : 1, jadi $n(\\text{H}_2) = 0{,}2$ mol; volume STP $= 0{,}2 \\times 22{,}4$. 3. $= 4{,}48\\ \\text{L}$." },
{ q: "Sebanyak 28 gram N₂ direaksikan dengan H₂ berlebih (N₂ + 3H₂ → 2NH₃). Massa NH₃ yang terbentuk adalah ... (M_r: N₂ = 28, NH₃ = 17)", options: ["17 g", "34 g", "51 g", "68 g"], answer: 1, solution: "1. $n(\\text{N}_2) = 28/28 = 1$ mol. 2. Perbandingan N₂ : NH₃ = 1 : 2, jadi $n(\\text{NH}_3) = 2 \\times 1 = 2$ mol. 3. Massa NH₃ $= 2 \\times 17 = 34\\ \\text{g}$." },
{ q: "Sebanyak 10 gram Ca direaksikan dengan 3,2 gram O₂ (2Ca + O₂ → 2CaO). Massa CaO yang terbentuk adalah ... (A_r: Ca = 40, O = 16)", options: ["11,2 g", "14 g", "5,6 g", "28 g"], answer: 0, solution: "1. $n(\\text{Ca}) = 10/40 = 0{,}25$ mol; $n(\\text{O}_2) = 3{,}2/32 = 0{,}1$ mol. 2. Untuk 0,25 mol Ca dibutuhkan $0{,}25/2 = 0{,}125$ mol O₂ (tersedia hanya 0,1 mol), jadi O₂ adalah pereaksi pembatas. Perbandingan O₂ : CaO = 1 : 2, maka $n(\\text{CaO}) = 2 \\times 0{,}1 = 0{,}2$ mol. 3. Massa CaO $= 0{,}2 \\times 56 = 11{,}2\\ \\text{g}$." },
{ q: "Sebanyak 0,5 mol suatu gas massanya 22 gram. Massa molar gas tersebut adalah ...", options: ["11 g/mol", "22 g/mol", "44 g/mol", "88 g/mol"], answer: 2, solution: "1. Diketahui $n = 0{,}5\\ \\text{mol}$ dan massa $= 22\\ \\text{g}$. 2. Gunakan rumus $M_r = \\frac{\\text{massa}}{n} = \\frac{22}{0{,}5}$. 3. $= 44\\ \\text{g/mol}$." },
{ q: "Hukum Proust (hukum perbandingan tetap) menyatakan bahwa ...", options: ["massa zat sebelum dan sesudah reaksi selalu sama", "volume gas-gas yang bereaksi berbanding sebagai bilangan bulat sederhana", "jumlah mol pereaksi selalu sama dengan jumlah mol produk", "perbandingan massa unsur-unsur dalam suatu senyawa selalu tetap"], answer: 3, solution: "1. Hukum Proust membahas susunan (komposisi) suatu senyawa. 2. Senyawa yang sama selalu tersusun dari unsur-unsur yang sama dengan perbandingan massa yang tetap, misalnya perbandingan massa H : O dalam air selalu 1 : 8. 3. Jadi perbandingan massa unsur-unsur dalam suatu senyawa selalu tetap." },
{ q: "Sebanyak 8 gram CH₄ dibakar sempurna (CH₄ + 2O₂ → CO₂ + 2H₂O). Volume gas CO₂ yang dihasilkan pada STP adalah ... (M_r CH₄ = 16)", options: ["5,6 L", "11,2 L", "22,4 L", "44,8 L"], answer: 1, solution: "1. $n(\\text{CH}_4) = 8/16 = 0{,}5$ mol. 2. Perbandingan CH₄ : CO₂ = 1 : 1, jadi $n(\\text{CO}_2) = 0{,}5$ mol; volume STP $= 0{,}5 \\times 22{,}4$. 3. $= 11{,}2\\ \\text{L}$." },
{ q: "Persen massa karbon dalam CO₂ adalah ... (A_r: C = 12, O = 16)", options: ["27,3%", "36,4%", "72,7%", "12%"], answer: 0, solution: "1. $M_r\\ \\text{CO}_2 = 12 + 2(16) = 44$. 2. Persen massa C $= \\frac{A_r\\ \\text{C}}{M_r\\ \\text{CO}_2} \\times 100\\% = \\frac{12}{44} \\times 100\\%$. 3. $= 27{,}3\\%$." },
{ q: "Sebanyak 6 gram Mg direaksikan dengan HCl berlebih (Mg + 2HCl → MgCl₂ + H₂). Volume H₂ yang dihasilkan pada STP adalah ... (A_r Mg = 24)", options: ["2,24 L", "11,2 L", "5,6 L", "22,4 L"], answer: 2, solution: "1. $n(\\text{Mg}) = 6/24 = 0{,}25$ mol. 2. Perbandingan Mg : H₂ = 1 : 1, jadi $n(\\text{H}_2) = 0{,}25$ mol; volume STP $= 0{,}25 \\times 22{,}4$. 3. $= 5{,}6\\ \\text{L}$." },
{ q: "Sebanyak 5 mol H₂ direaksikan dengan 2 mol O₂ (2H₂ + O₂ → 2H₂O). Zat yang tersisa beserta jumlahnya adalah ...", options: ["O₂ tersisa 1 mol", "H₂ tersisa 2 mol", "tidak ada yang tersisa", "H₂ tersisa 1 mol"], answer: 3, solution: "1. Perbandingan H₂ : O₂ = 2 : 1. Untuk 2 mol O₂ dibutuhkan $2 \\times 2 = 4$ mol H₂. 2. Tersedia 5 mol H₂, sehingga O₂ habis lebih dulu dan H₂ tersisa $5 - 4 = 1$ mol. 3. Jadi H₂ tersisa sebanyak 1 mol." },
{ q: "Sebanyak 4,6 gram Na direaksikan dengan Cl₂ berlebih (2Na + Cl₂ → 2NaCl). Massa NaCl yang terbentuk adalah ... (A_r: Na = 23, Cl = 35,5)", options: ["5,85 g", "11,7 g", "23,4 g", "58,5 g"], answer: 1, solution: "1. $n(\\text{Na}) = 4{,}6/23 = 0{,}2$ mol. 2. Perbandingan Na : NaCl = 2 : 2 = 1 : 1, jadi $n(\\text{NaCl}) = 0{,}2$ mol; $M_r\\ \\text{NaCl} = 23 + 35{,}5 = 58{,}5$. 3. Massa NaCl $= 0{,}2 \\times 58{,}5 = 11{,}7\\ \\text{g}$." },
{ q: "Sebanyak 2,4 gram Mg dibakar dalam oksigen menghasilkan 4,0 gram MgO. Rumus empiris senyawa yang terbentuk adalah ... (A_r: Mg = 24, O = 16)", options: ["MgO", "Mg₂O", "MgO₂", "Mg₂O₃"], answer: 0, solution: "1. Massa O yang bereaksi $= 4{,}0 - 2{,}4 = 1{,}6$ g. Mol Mg $= 2{,}4/24 = 0{,}1$; mol O $= 1{,}6/16 = 0{,}1$. 2. Perbandingan mol Mg : O $= 0{,}1 : 0{,}1 = 1 : 1$. 3. Jadi rumus empirisnya adalah MgO." },
{ q: "Pada reaksi 2SO₂ + O₂ → 2SO₃, dari 12,8 gram SO₂ diperoleh 12 gram SO₃. Persen hasil reaksi tersebut adalah ... (M_r: SO₂ = 64, SO₃ = 80)", options: ["60%", "80%", "75%", "90%"], answer: 2, solution: "1. $n(\\text{SO}_2) = 12{,}8/64 = 0{,}2$ mol; perbandingan SO₂ : SO₃ = 1 : 1, jadi $n(\\text{SO}_3)$ teoritis $= 0{,}2$ mol. 2. Massa teoritis SO₃ $= 0{,}2 \\times 80 = 16$ g. 3. Persen hasil $= \\frac{12}{16} \\times 100\\% = 75\\%$." },
{ q: "Jumlah mol dalam 44 gram CO₂ adalah ... (M_r CO₂ = 44)", options: ["0,5 mol", "2 mol", "0,1 mol", "1 mol"], answer: 3, solution: "1. Diketahui massa $= 44\\ \\text{g}$ dan $M_r = 44$. 2. Gunakan rumus $n = \\frac{\\text{massa}}{M_r} = \\frac{44}{44}$. 3. $n = 1\\ \\text{mol}$." },
{ q: "Sebanyak 24,5 gram KClO₃ dipanaskan (2KClO₃ → 2KCl + 3O₂). Massa O₂ yang dihasilkan adalah ... (M_r: KClO₃ = 122,5, O₂ = 32)", options: ["16 g", "9,6 g", "6,4 g", "19,2 g"], answer: 1, solution: "1. $n(\\text{KClO}_3) = 24{,}5/122{,}5 = 0{,}2$ mol. 2. Perbandingan KClO₃ : O₂ = 2 : 3, jadi $n(\\text{O}_2) = \\frac{3}{2} \\times 0{,}2 = 0{,}3$ mol. 3. Massa O₂ $= 0{,}3 \\times 32 = 9{,}6\\ \\text{g}$." },
{ q: "Massa 0,5 mol H₂SO₄ adalah ... (M_r H₂SO₄ = 98)", options: ["49 g", "98 g", "196 g", "24,5 g"], answer: 0, solution: "1. Diketahui $n = 0{,}5\\ \\text{mol}$ dan $M_r = 98$. 2. Gunakan rumus massa $= n \\times M_r = 0{,}5 \\times 98$. 3. Massa $= 49\\ \\text{g}$." },
{ q: "Konsentrasi larutan yang mengandung 0,2 mol zat dalam 500 mL larutan adalah ...", options: ["0,2 M", "0,1 M", "0,4 M", "0,8 M"], answer: 2, solution: "1. Diketahui $n = 0{,}2\\ \\text{mol}$ dan $V = 500\\ \\text{mL} = 0{,}5\\ \\text{L}$. 2. Gunakan rumus molaritas $M = \\frac{n}{V} = \\frac{0{,}2}{0{,}5}$. 3. $M = 0{,}4\\ \\text{M}$." },
{ q: "Molalitas larutan yang dibuat dari 0,5 mol urea dalam 1000 gram air adalah ...", options: ["0,25 m", "1 m", "2 m", "0,5 m"], answer: 3, solution: "1. Diketahui $n = 0{,}5\\ \\text{mol}$ dan massa pelarut $= 1000\\ \\text{g} = 1\\ \\text{kg}$. 2. Gunakan rumus molalitas $m = \\frac{n}{\\text{massa pelarut (kg)}} = \\frac{0{,}5}{1}$. 3. $m = 0{,}5\\ \\text{m}$." },
{ q: "Dalam larutan yang mengandung 1 mol zat A dan 3 mol zat B, fraksi mol zat A adalah ...", options: ["0,75", "0,25", "0,33", "1"], answer: 1, solution: "1. Diketahui $n_A = 1$ mol dan $n_B = 3$ mol, total $= 4$ mol. 2. Gunakan rumus fraksi mol $X_A = \\frac{n_A}{n_A + n_B} = \\frac{1}{4}$. 3. $X_A = 0{,}25$." },
{ q: "Sebanyak 20 gram gula dilarutkan dalam 180 gram air. Kadar gula dalam larutan tersebut adalah ...", options: ["10%", "20%", "11,1%", "9%"], answer: 0, solution: "1. Massa zat terlarut = 20 g; massa larutan $= 20 + 180 = 200$ g. 2. Kadar $= \\frac{20}{200} \\times 100\\%$. 3. $= 10\\%$." },
{ q: "Sebanyak 50 mL larutan 4 M diencerkan dengan air hingga volumenya 200 mL. Konsentrasi larutan setelah pengenceran adalah ...", options: ["2 M", "0,5 M", "1 M", "8 M"], answer: 2, solution: "1. Gunakan rumus pengenceran $M_1V_1 = M_2V_2$. 2. $4 \\times 50 = M_2 \\times 200$. 3. $M_2 = \\frac{200}{200} = 1\\ \\text{M}$." },
{ q: "Sebanyak 250 mL larutan 2 M diencerkan hingga konsentrasinya menjadi 0,5 M. Volume larutan setelah pengenceran adalah ...", options: ["500 mL", "125 mL", "750 mL", "1000 mL"], answer: 3, solution: "1. Gunakan rumus pengenceran $M_1V_1 = M_2V_2$. 2. $2 \\times 250 = 0{,}5 \\times V_2$. 3. $V_2 = \\frac{500}{0{,}5} = 1000\\ \\text{mL}$." },
{ q: "Titik didih larutan urea 1 molal adalah ... (K_b air = 0,52 °C/m)", options: ["100 °C", "100,52 °C", "99,48 °C", "101,04 °C"], answer: 1, solution: "1. Urea adalah nonelektrolit sehingga faktor van't Hoff $i = 1$. 2. Kenaikan titik didih $\\Delta T_b = m \\times K_b \\times i = 1 \\times 0{,}52 \\times 1 = 0{,}52$ °C. 3. Titik didih larutan $= 100 + 0{,}52 = 100{,}52$ °C." },
{ q: "Titik beku larutan NaCl 1 molal adalah ... (K_f air = 1,86 °C/m, NaCl terionisasi sempurna)", options: ["−3,72 °C", "−1,86 °C", "−0,93 °C", "3,72 °C"], answer: 0, solution: "1. NaCl terionisasi sempurna menjadi Na⁺ dan Cl⁻, jadi faktor van't Hoff $i = 2$. 2. Penurunan titik beku $\\Delta T_f = m \\times K_f \\times i = 1 \\times 1{,}86 \\times 2 = 3{,}72$ °C. 3. Titik beku larutan $= 0 - 3{,}72 = -3{,}72$ °C." },
{ q: "Tekanan osmosis larutan sukrosa 0,1 M pada suhu 27 °C adalah ... (R = 0,082 L·atm/mol·K)", options: ["1,23 atm", "24,6 atm", "2,46 atm", "0,246 atm"], answer: 2, solution: "1. Diketahui $M = 0{,}1\\ \\text{M}$ dan $T = 27$ °C $= 300\\ \\text{K}$. 2. Gunakan rumus $\\pi = MRT = 0{,}1 \\times 0{,}082 \\times 300$. 3. $\\pi = 2{,}46\\ \\text{atm}$." },
{ q: "Fraksi mol zat terlarut dalam suatu larutan adalah 0,1 dan tekanan uap jenuh pelarut murninya 100 mmHg. Penurunan tekanan uap larutan tersebut adalah ...", options: ["90 mmHg", "1 mmHg", "0,1 mmHg", "10 mmHg"], answer: 3, solution: "1. Diketahui $X_{\\text{terlarut}} = 0{,}1$ dan $P^\\circ = 100\\ \\text{mmHg}$. 2. Gunakan rumus $\\Delta P = X_{\\text{terlarut}} \\times P^\\circ = 0{,}1 \\times 100$. 3. $\\Delta P = 10\\ \\text{mmHg}$." },
{ q: "Sifat koligatif larutan bergantung pada ...", options: ["jenis zat terlarut", "jumlah partikel zat terlarut", "warna larutan", "massa jenis pelarut"], answer: 1, solution: "1. Sifat koligatif meliputi penurunan tekanan uap, kenaikan titik didih, penurunan titik beku, dan tekanan osmosis. 2. Keempat sifat ini hanya dipengaruhi oleh banyaknya partikel zat terlarut, bukan jenisnya. 3. Jadi sifat koligatif bergantung pada jumlah partikel zat terlarut." },
{ q: "Pada konsentrasi molal yang sama, larutan yang mengalami penurunan titik beku paling besar adalah larutan ...", options: ["NaCl", "glukosa", "urea", "sukrosa"], answer: 0, solution: "1. Penurunan titik beku dirumuskan $\\Delta T_f = m \\times K_f \\times i$, dengan $i$ faktor van't Hoff. 2. Glukosa, urea, dan sukrosa adalah nonelektrolit ($i = 1$), sedangkan NaCl terionisasi menjadi 2 ion ($i = 2$). 3. Nilai $i$ terbesar menghasilkan $\\Delta T_f$ terbesar, yaitu larutan NaCl." },
{ q: "Busa sabun merupakan contoh koloid jenis ...", options: ["emulsi", "sol", "buih", "gel"], answer: 2, solution: "1. Koloid dibedakan berdasarkan wujud fase terdispersi dan medium pendispersi. 2. Busa sabun tersusun dari gelembung gas yang terdispersi dalam zat cair. 3. Sistem koloid gas dalam cair disebut buih." },
{ q: "Agar-agar dan jeli merupakan contoh koloid jenis ...", options: ["sol", "emulsi", "aerosol", "gel"], answer: 3, solution: "1. Agar-agar tersusun dari zat cair yang terdispersi dalam zat padat sehingga bentuknya kenyal dan kaku. 2. Sistem koloid cair dalam padat disebut gel. 3. Jadi agar-agar dan jeli termasuk koloid jenis gel." },
{ q: "Asap merupakan contoh koloid jenis ...", options: ["aerosol cair", "aerosol padat", "emulsi", "buih"], answer: 1, solution: "1. Asap tersusun dari partikel-partikel padat yang sangat halus. 2. Partikel padat tersebut terdispersi di udara (gas). 3. Sistem koloid padat dalam gas disebut aerosol padat." },
{ q: "Pemisahan partikel koloid dari ion-ion pengotor menggunakan membran semipermeabel disebut ...", options: ["dialisis", "elektroforesis", "koagulasi", "adsorpsi"], answer: 0, solution: "1. Ion-ion pengotor berukuran jauh lebih kecil daripada partikel koloid. 2. Membran semipermeabel hanya dapat dilewati partikel kecil (ion), sedangkan partikel koloid tertahan. 3. Proses pemurnian koloid dengan cara ini disebut dialisis." },
{ q: "Pergerakan partikel-partikel koloid menuju elektrode ketika diberi medan listrik disebut ...", options: ["gerak Brown", "efek Tyndall", "elektroforesis", "dialisis"], answer: 2, solution: "1. Partikel koloid bermuatan listrik karena menyerap ion dari mediumnya. 2. Dalam medan listrik, partikel bermuatan akan bergerak menuju elektrode yang berlawanan muatannya. 3. Peristiwa ini disebut elektroforesis." },
{ q: "Pada pengolahan lateks menjadi karet, penambahan asam format bertujuan untuk ...", options: ["melarutkan partikel karet", "menambah muatan partikel koloid", "menaikkan viskositas lateks", "mengkoagulasikan partikel-partikel koloid karet"], answer: 3, solution: "1. Lateks adalah koloid dengan partikel karet terdispersi dalam air, stabil karena muatannya. 2. Asam format (elektrolit) menetralkan muatan partikel koloid sehingga kestabilannya hilang. 3. Partikel-partikel kemudian menggumpal (koagulasi) dan dapat dipisahkan sebagai karet." },
{ q: "Norit (karbon aktif) dapat menyerap zat warna dan racun karena memiliki sifat ...", options: ["koagulasi", "adsorpsi", "dialisis", "elektroforesis"], answer: 1, solution: "1. Norit memiliki permukaan yang sangat luas dan berpori. 2. Zat warna dan racun menempel pada permukaan norit tanpa bereaksi kimia. 3. Peristiwa penyerapan pada permukaan ini disebut adsorpsi." },
{ q: "Sebanyak 9 gram glukosa (M_r = 180) dilarutkan dalam 90 gram air (M_r = 18). Fraksi mol glukosa dalam larutan adalah ...", options: ["0,01", "0,1", "0,5", "0,05"], answer: 0, solution: "1. Hitung mol: $n(\\text{glukosa}) = 9/180 = 0{,}05$ mol; $n(\\text{air}) = 90/18 = 5$ mol. 2. Fraksi mol glukosa $X = \\frac{0{,}05}{0{,}05 + 5} = \\frac{0{,}05}{5{,}05}$. 3. $X \\approx 0{,}01$." },
{ q: "Diketahui $\\Delta H_f^\\circ$ H₂O(l) $= -285\\ \\text{kJ/mol}$. Nilai $\\Delta H$ untuk reaksi $2\\text{H}_2(g) + \\text{O}_2(g) \\to 2\\text{H}_2\\text{O}(l)$ adalah ...", options: ["−285 kJ", "−570 kJ", "+570 kJ", "−1140 kJ"], answer: 1, solution: "1. Diketahui $\\Delta H_f^\\circ(\\text{H}_2\\text{O}, l) = -285\\ \\text{kJ/mol}$, sedangkan $\\Delta H_f^\\circ$ unsur bebas (H₂, O₂) $= 0$. 2. Gunakan rumus $\\Delta H = \\sum \\Delta H_f^\\circ(\\text{produk}) - \\sum \\Delta H_f^\\circ(\\text{pereaksi}) = 2(-285) - 0$. 3. Jadi jawabannya $\\Delta H = -570\\ \\text{kJ}$." },
{ q: "Diketahui: (1) $\\text{C} + \\text{O}_2 \\to \\text{CO}_2$ $\\Delta H = -394\\ \\text{kJ}$; (2) $\\text{CO} + \\frac{1}{2}\\text{O}_2 \\to \\text{CO}_2$ $\\Delta H = -283\\ \\text{kJ}$. Nilai $\\Delta H$ untuk reaksi $\\text{C} + \\frac{1}{2}\\text{O}_2 \\to \\text{CO}$ adalah ...", options: ["−677 kJ", "+111 kJ", "−111 kJ", "−283 kJ"], answer: 2, solution: "1. Reaksi target diperoleh dari reaksi (1) ditambah kebalikan reaksi (2). 2. Reaksi (2) dibalik menjadi $\\text{CO}_2 \\to \\text{CO} + \\frac{1}{2}\\text{O}_2$ dengan $\\Delta H = +283\\ \\text{kJ}$ (tanda berubah). 3. Jumlahkan: $(-394) + (+283) = -111\\ \\text{kJ}$, jadi jawabannya $-111\\ \\text{kJ}$." },
{ q: "Diketahui: $\\text{N}_2 + \\text{O}_2 \\to 2\\text{NO}$ $\\Delta H = +180\\ \\text{kJ}$ dan $2\\text{NO} + \\text{O}_2 \\to 2\\text{NO}_2$ $\\Delta H = -114\\ \\text{kJ}$. Berdasarkan hukum Hess, $\\Delta H$ untuk $\\text{N}_2 + 2\\text{O}_2 \\to 2\\text{NO}_2$ adalah ...", options: ["+66 kJ", "+294 kJ", "−66 kJ", "−294 kJ"], answer: 0, solution: "1. Kedua reaksi tahap jika dijumlahkan: $\\text{N}_2 + \\text{O}_2 + 2\\text{NO} + \\text{O}_2 \\to 2\\text{NO} + 2\\text{NO}_2$. 2. Spesi 2NO di kedua ruas saling meniadakan sehingga diperoleh reaksi target $\\text{N}_2 + 2\\text{O}_2 \\to 2\\text{NO}_2$. 3. $\\Delta H = (+180) + (-114) = +66\\ \\text{kJ}$." },
{ q: "Pada diagram tingkat energi, energi pereaksi $= 50\\ \\text{kJ/mol}$, energi kompleks teraktivasi $= 130\\ \\text{kJ/mol}$, dan energi produk $= 20\\ \\text{kJ/mol}$. Energi aktivasi reaksi maju adalah ...", options: ["30 kJ/mol", "−30 kJ/mol", "110 kJ/mol", "80 kJ/mol"], answer: 3, solution: "1. Energi aktivasi $(E_a)$ adalah selisih energi kompleks teraktivasi (puncak kurva) dan energi pereaksi. 2. $E_a = 130 - 50 = 80\\ \\text{kJ/mol}$. 3. Jadi jawabannya $80\\ \\text{kJ/mol}$. (Sebagai catatan, $\\Delta H = 20 - 50 = -30\\ \\text{kJ/mol}$.)" },
{ q: "Diketahui $\\Delta H_c^\\circ$ CH₄ $= -890\\ \\text{kJ/mol}$. Kalor yang dilepaskan pada pembakaran sempurna $8$ gram CH₄ adalah ... ($M_r$ CH₄ $= 16$)", options: ["445 kJ", "890 kJ", "222,5 kJ", "1780 kJ"], answer: 0, solution: "1. Diketahui massa CH₄ $= 8\\ \\text{g}$ dan $M_r = 16$, maka $n = \\frac{8}{16} = 0{,}5\\ \\text{mol}$. 2. Kalor yang dilepaskan $q = n \\times |\\Delta H_c^\\circ| = 0{,}5 \\times 890$. 3. Jadi jawabannya $q = 445\\ \\text{kJ}$." },
{ q: "Diketahui $\\Delta H_f^\\circ$ CaCO₃ $= -1207\\ \\text{kJ/mol}$. Nilai $\\Delta H$ untuk reaksi penguraian $\\text{CaCO}_3 \\to \\text{CaO} + \\text{CO}_2$ adalah ...", options: ["−1207 kJ/mol", "−603,5 kJ/mol", "0 kJ/mol", "+1207 kJ/mol"], answer: 3, solution: "1. Reaksi penguraian CaCO₃ merupakan kebalikan dari reaksi pembentukannya. 2. Menurut hukum Hess, membalik arah reaksi mengubah tanda $\\Delta H$: $\\Delta H_{\\text{urai}} = -\\Delta H_f^\\circ = -(-1207)$. 3. Jadi jawabannya $+1207\\ \\text{kJ/mol}$ (reaksi endoterm)." },
{ q: "Diketahui energi ikatan: H−H $= 436$, Cl−Cl $= 242$, H−Cl $= 431\\ \\text{kJ/mol}$. Nilai $\\Delta H$ untuk reaksi $\\text{H}_2 + \\text{Cl}_2 \\to 2\\text{HCl}$ adalah ...", options: ["+184 kJ", "−184 kJ", "−862 kJ", "+862 kJ"], answer: 1, solution: "1. Energi untuk memutuskan ikatan: H−H $+$ Cl−Cl $= 436 + 242 = 678\\ \\text{kJ}$. 2. Energi yang dilepas saat membentuk $2$ ikatan H−Cl $= 2 \\times 431 = 862\\ \\text{kJ}$. 3. $\\Delta H = \\sum E_{\\text{putus}} - \\sum E_{\\text{bentuk}} = 678 - 862 = -184\\ \\text{kJ}$." },
{ q: "Pada diagram tingkat energi suatu reaksi, tingkat energi pereaksi $= 200\\ \\text{kJ/mol}$ dan tingkat energi produk $= 350\\ \\text{kJ/mol}$. Nilai $\\Delta H$ dan jenis reaksi tersebut adalah ...", options: ["$\\Delta H = -150\\ \\text{kJ/mol}$, eksoterm", "$\\Delta H = +550\\ \\text{kJ/mol}$, endoterm", "$\\Delta H = +150\\ \\text{kJ/mol}$, endoterm", "$\\Delta H = -550\\ \\text{kJ/mol}$, eksoterm"], answer: 2, solution: "1. $\\Delta H = E_{\\text{produk}} - E_{\\text{pereaksi}} = 350 - 200 = +150\\ \\text{kJ/mol}$. 2. $\\Delta H$ positif berarti sistem menyerap kalor dari lingkungan. 3. Reaksi yang menyerap kalor disebut endoterm, jadi jawabannya $\\Delta H = +150\\ \\text{kJ/mol}$, endoterm." },
{ q: "Berdasarkan data reaksi berikut: (1) $\\text{C} + \\text{O}_2 \\to \\text{CO}_2$, $\\Delta H = -394\\ \\text{kJ}$; (2) $\\text{H}_2 + \\frac{1}{2}\\text{O}_2 \\to \\text{H}_2\\text{O}$, $\\Delta H = -286\\ \\text{kJ}$; (3) $2\\text{CO}_2 + \\text{H}_2\\text{O} \\to \\text{C}_2\\text{H}_2 + \\frac{5}{2}\\text{O}_2$, $\\Delta H = +1300\\ \\text{kJ}$. Nilai $\\Delta H_f^\\circ$ C₂H₂ adalah ...", options: ["+226 kJ/mol", "−226 kJ/mol", "+1300 kJ/mol", "−788 kJ/mol"], answer: 0, solution: "1. Susun tahap-tahap agar menghasilkan $2\\text{C} + \\text{H}_2 \\to \\text{C}_2\\text{H}_2$: kalikan reaksi (1) dengan $2$, reaksi (2) dan (3) tetap. 2. $2 \\times (-394) = -788\\ \\text{kJ}$; ditambah $(-286)\\ \\text{kJ}$ dan $(+1300)\\ \\text{kJ}$. 3. Jumlahkan: $-788 + (-286) + 1300 = +226\\ \\text{kJ/mol}$." },
{ q: "Sebanyak $100$ gram air dipanaskan sehingga suhunya naik $10^\\circ\\text{C}$. Kalor yang diserap air adalah ... (kalor jenis air $= 4{,}2\\ \\text{J/g}^\\circ\\text{C}$)", options: ["420 J", "42 kJ", "0,42 kJ", "4,2 kJ"], answer: 3, solution: "1. Diketahui $m = 100\\ \\text{g}$, $c = 4{,}2\\ \\text{J/g}^\\circ\\text{C}$, $\\Delta T = 10^\\circ\\text{C}$. 2. Gunakan rumus kalorimetri $q = m \\times c \\times \\Delta T = 100 \\times 4{,}2 \\times 10$. 3. $q = 4200\\ \\text{J} = 4{,}2\\ \\text{kJ}$." },
{ q: "Pernyataan yang TEPAT mengenai hukum Hess adalah ...", options: ["perubahan entalpi bergantung pada jalannya reaksi", "perubahan entalpi hanya bergantung pada keadaan awal dan keadaan akhir", "perubahan entalpi selalu bernilai negatif", "perubahan entalpi sama dengan energi aktivasi"], answer: 1, solution: "1. Hukum Hess menyatakan bahwa $\\Delta H$ suatu reaksi tidak bergantung pada jalannya (tahapan) reaksi. 2. Artinya, $\\Delta H$ hanya ditentukan oleh keadaan awal (pereaksi) dan keadaan akhir (produk). 3. Karena itu $\\Delta H$ dapat dihitung melalui tahap-tahap apa pun selama keadaan awal dan akhirnya sama." },
{ q: "Diketahui: $\\text{S} + \\text{O}_2 \\to \\text{SO}_2$ $\\Delta H = -297\\ \\text{kJ}$ dan $2\\text{SO}_2 + \\text{O}_2 \\to 2\\text{SO}_3$ $\\Delta H = -198\\ \\text{kJ}$. $\\Delta H$ pembentukan $1$ mol SO₃ dari unsur-unsurnya adalah ...", options: ["−495 kJ", "−198 kJ", "−396 kJ", "+396 kJ"], answer: 2, solution: "1. Reaksi target: $\\text{S} + \\frac{3}{2}\\text{O}_2 \\to \\text{SO}_3$, diperoleh dari reaksi pertama ditambah setengah reaksi kedua. 2. Setengah reaksi kedua: $\\text{SO}_2 + \\frac{1}{2}\\text{O}_2 \\to \\text{SO}_3$ dengan $\\Delta H = \\frac{-198}{2} = -99\\ \\text{kJ}$. 3. Jumlahkan: $(-297) + (-99) = -396\\ \\text{kJ}$." },
{ q: "Reaksi fotosintesis $6\\text{CO}_2 + 6\\text{H}_2\\text{O} \\to \\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\text{O}_2$ memiliki $\\Delta H = +2800\\ \\text{kJ}$. Reaksi ini tergolong ...", options: ["endoterm karena menyerap energi cahaya matahari", "eksoterm karena melepaskan energi cahaya", "reaksi netralisasi", "reaksi pembakaran"], answer: 0, solution: "1. $\\Delta H$ bernilai positif $(+2800\\ \\text{kJ})$, artinya entalpi produk lebih besar daripada entalpi pereaksi. 2. Energi tambahan berasal dari cahaya matahari yang diserap tumbuhan hijau. 3. Reaksi yang menyerap energi disebut reaksi endoterm." },
{ q: "Pengaruh katalis pada diagram tingkat energi suatu reaksi adalah ...", options: ["menaikkan tingkat energi produk", "menaikkan tingkat energi pereaksi", "memperbesar $\\Delta H$ reaksi", "menurunkan energi aktivasi tanpa mengubah $\\Delta H$"], answer: 3, solution: "1. Katalis menyediakan jalur reaksi alternatif dengan energi aktivasi $(E_a)$ yang lebih rendah (puncak kurva lebih rendah). 2. Tingkat energi pereaksi dan produk tidak berubah, sehingga selisihnya $(\\Delta H)$ tetap sama. 3. Jadi katalis menurunkan energi aktivasi tanpa mengubah $\\Delta H$ reaksi." },
{ q: "Diketahui $\\Delta H_c^\\circ$ C₂H₅OH $= -1368\\ \\text{kJ/mol}$, $\\Delta H_f^\\circ$ CO₂ $= -394\\ \\text{kJ/mol}$, $\\Delta H_f^\\circ$ H₂O $= -286\\ \\text{kJ/mol}$. $\\Delta H_f^\\circ$ C₂H₅OH adalah ...", options: ["−1368 kJ/mol", "−278 kJ/mol", "+278 kJ/mol", "−1646 kJ/mol"], answer: 1, solution: "1. Reaksi pembakaran: $\\text{C}_2\\text{H}_5\\text{OH} + 3\\text{O}_2 \\to 2\\text{CO}_2 + 3\\text{H}_2\\text{O}$. 2. $\\Delta H_c^\\circ = [2(-394) + 3(-286)] - \\Delta H_f^\\circ(\\text{C}_2\\text{H}_5\\text{OH}) = -1646 - \\Delta H_f^\\circ$. 3. $-1368 = -1646 - \\Delta H_f^\\circ$, sehingga $\\Delta H_f^\\circ = -1646 + 1368 = -278\\ \\text{kJ/mol}$." },
{ q: "Suatu reaksi memiliki $\\Delta H = -50\\ \\text{kJ/mol}$. Jika yang bereaksi sebanyak $2$ mol, kalor yang dilepaskan adalah ...", options: ["50 kJ", "25 kJ", "100 kJ", "200 kJ"], answer: 2, solution: "1. Diketahui $\\Delta H = -50\\ \\text{kJ/mol}$ (tanda negatif berarti kalor dilepaskan) dan $n = 2\\ \\text{mol}$. 2. Kalor yang dilepaskan $q = n \\times |\\Delta H| = 2 \\times 50$. 3. Jadi jawabannya $100\\ \\text{kJ}$." },
{ q: "Dari data percobaan: jika konsentrasi A dinaikkan $2$ kali, laju reaksi menjadi $4$ kali. Orde reaksi terhadap A adalah ...", options: ["2", "1", "4", "0"], answer: 0, solution: "1. Hubungan laju dan konsentrasi: $v \\propto [\\text{A}]^m$, dengan $m$ = orde terhadap A. 2. Konsentrasi naik $2$ kali menyebabkan laju naik $4$ kali, berarti $2^m = 4$. 3. $m = 2$, jadi orde reaksi terhadap A adalah $2$." },
{ q: "Persamaan laju $v = k[\\text{A}]^2[\\text{B}]$. Jika konsentrasi A dinaikkan $3$ kali dan konsentrasi B dinaikkan $2$ kali, laju reaksi menjadi ... semula.", options: ["6 kali", "9 kali", "12 kali", "18 kali"], answer: 3, solution: "1. Faktor perubahan laju $= (\\text{faktor [A]})^{\\text{orde A}} \\times (\\text{faktor [B]})^{\\text{orde B}}$. 2. $= 3^2 \\times 2^1 = 9 \\times 2$. 3. Jadi laju reaksi menjadi $18$ kali semula." },
{ q: "Suatu reaksi memiliki persamaan laju $v = k[\\text{A}][\\text{B}]^2$. Orde total reaksi tersebut adalah ...", options: ["2", "3", "4", "1"], answer: 1, solution: "1. Orde total adalah jumlah seluruh pangkat konsentrasi pada persamaan laju. 2. Pangkat [A] $= 1$ dan pangkat [B] $= 2$. 3. Orde total $= 1 + 2 = 3$." },
{ q: "Menurut teori tumbukan, tumbukan antarpartikel pereaksi menghasilkan reaksi (tumbukan efektif) jika ...", options: ["energi tumbukan sangat kecil", "partikel-partikel dalam keadaan diam", "energi tumbukan ≥ energi aktivasi dan orientasinya tepat", "suhu sistem diturunkan serendah mungkin"], answer: 2, solution: "1. Tidak semua tumbukan menghasilkan reaksi; hanya tumbukan efektif yang berhasil. 2. Syarat tumbukan efektif ada dua: energi kinetik partikel minimal sama dengan energi aktivasi $(E_a)$ dan arah (orientasi) tumbukan tepat. 3. Jadi jawabannya: energi tumbukan ≥ energi aktivasi dan orientasinya tepat." },
{ q: "Peran katalis dalam suatu reaksi kimia adalah ...", options: ["menurunkan energi aktivasi tanpa ikut bereaksi secara permanen", "menaikkan energi aktivasi agar reaksi lebih cepat", "mengubah $\\Delta H$ reaksi menjadi negatif", "habis terpakai selama reaksi berlangsung"], answer: 0, solution: "1. Katalis menyediakan mekanisme alternatif dengan energi aktivasi lebih rendah. 2. Katalis tidak mengubah $\\Delta H$ dan pada akhir reaksi diperoleh kembali (tidak habis terpakai). 3. Jadi katalis menurunkan energi aktivasi tanpa ikut bereaksi secara permanen." },
{ q: "Pada grafik konsentrasi terhadap waktu, laju reaksi sesaat pada suatu titik ditentukan dari ...", options: ["luas daerah di bawah kurva", "titik potong kurva dengan sumbu waktu", "jarak titik ke sumbu konsentrasi", "kemiringan (gradien) garis singgung kurva di titik itu"], answer: 3, solution: "1. Laju reaksi menyatakan perubahan konsentrasi per satuan waktu, $v = \\frac{\\Delta[\\ ]}{\\Delta t}$. 2. Pada grafik, nilai $\\frac{\\Delta[\\ ]}{\\Delta t}$ sama dengan kemiringan garis singgung kurva di titik tersebut. 3. Jadi laju sesaat ditentukan dari kemiringan (gradien) garis singgung kurva." },
{ q: "Katalis homogen adalah katalis yang ...", options: ["berwujud padat dalam reaksi berfase gas", "fasenya sama dengan fase zat-zat pereaksi", "fasenya berbeda dengan fase zat-zat pereaksi", "hanya bekerja pada suhu sangat tinggi"], answer: 1, solution: "1. Katalis dibedakan menjadi homogen dan heterogen berdasarkan fasenya relatif terhadap pereaksi. 2. Katalis homogen memiliki fase yang sama dengan pereaksi, misalnya katalis cair dalam reaksi berfase cair. 3. Jika fasenya berbeda (misalnya padat dalam sistem gas), disebut katalis heterogen." },
{ q: "Suatu reaksi selesai dalam $120$ detik pada suhu $25^\\circ\\text{C}$. Jika laju reaksi menjadi $2$ kali lipat setiap kenaikan suhu $10^\\circ\\text{C}$, waktu yang dibutuhkan pada suhu $45^\\circ\\text{C}$ adalah ...", options: ["60 detik", "90 detik", "30 detik", "15 detik"], answer: 2, solution: "1. Kenaikan suhu $= 45 - 25 = 20^\\circ\\text{C}$, setara dengan $2$ kali kenaikan $10^\\circ\\text{C}$. 2. Laju menjadi $2^2 = 4$ kali lebih cepat, sehingga waktu reaksi menjadi $\\frac{1}{4}$ kali semula. 3. $t = \\frac{120}{4} = 30$ detik." },
{ q: "Setiap kenaikan suhu $10^\\circ\\text{C}$, laju reaksi menjadi $2$ kali lebih cepat. Jika suhu dinaikkan dari $30^\\circ\\text{C}$ menjadi $60^\\circ\\text{C}$, laju reaksi menjadi ... semula.", options: ["8 kali", "3 kali", "6 kali", "4 kali"], answer: 0, solution: "1. Kenaikan suhu $= 60 - 30 = 30^\\circ\\text{C}$, setara dengan $3$ kali kenaikan $10^\\circ\\text{C}$. 2. Setiap kenaikan $10^\\circ\\text{C}$ laju menjadi $2$ kali, sehingga faktor total $= 2^3$. 3. Jadi laju reaksi menjadi $8$ kali semula." },
{ q: "Jika data laju reaksi diplot sebagai grafik $\\log v$ terhadap $\\log[\\text{A}]$ dan diperoleh garis lurus, kemiringan (slope) garis tersebut menyatakan ...", options: ["tetapan laju reaksi", "energi aktivasi", "waktu paruh reaksi", "orde reaksi terhadap A"], answer: 3, solution: "1. Dari $v = k[\\text{A}]^m$ diperoleh $\\log v = \\log k + m \\cdot \\log[\\text{A}]$. 2. Ini adalah persamaan garis lurus $y = a + bx$ dengan kemiringan $b = m$. 3. Jadi kemiringan garis menyatakan orde reaksi terhadap A." },
{ q: "Waktu paruh suatu reaksi orde satu adalah $10$ menit. Jika konsentrasi awal pereaksi $= 0{,}8\\ \\text{M}$, konsentrasi yang tersisa setelah $30$ menit adalah ...", options: ["0,4 M", "0,1 M", "0,2 M", "0,05 M"], answer: 1, solution: "1. $30$ menit $= 3$ kali waktu paruh. 2. Setiap satu waktu paruh konsentrasi menjadi setengahnya, sehingga tersisa $(\\frac{1}{2})^3 = \\frac{1}{8}$ bagian. 3. $[\\text{A}] = \\frac{1}{8} \\times 0{,}8 = 0{,}1\\ \\text{M}$." },
{ q: "Data percobaan: pada konsentrasi A tetap, konsentrasi B dinaikkan $2$ kali menyebabkan laju reaksi menjadi $2$ kali. Orde reaksi terhadap B adalah ...", options: ["0", "2", "1", "3"], answer: 2, solution: "1. Hubungan $v \\propto [\\text{B}]^n$, dengan $n$ = orde terhadap B. 2. Konsentrasi B naik $2$ kali dan laju naik $2$ kali, berarti $2^n = 2$. 3. $n = 1$, jadi orde reaksi terhadap B adalah $1$." },
{ q: "Percobaan 1: $[\\text{A}] = 0{,}1\\ \\text{M}$, laju $= 2 \\times 10^{-3}\\ \\text{M/s}$. Percobaan 2: $[\\text{A}] = 0{,}2\\ \\text{M}$, laju tetap $2 \\times 10^{-3}\\ \\text{M/s}$ (konsentrasi zat lain tetap). Orde reaksi terhadap A adalah ...", options: ["0", "1", "2", "3"], answer: 0, solution: "1. Konsentrasi A dinaikkan $2$ kali tetapi laju reaksi tidak berubah. 2. Berarti $2^m = 1$, sehingga $m = 0$. 3. Jadi orde reaksi terhadap A adalah $0$ (laju tidak bergantung pada [A])." },
{ q: "Pengaruh katalis terhadap sistem reaksi yang dapat mencapai kesetimbangan adalah ...", options: ["menggeser kesetimbangan ke arah produk", "menggeser kesetimbangan ke arah pereaksi", "mempercepat tercapainya kesetimbangan tanpa menggeser posisinya", "mengubah nilai tetapan kesetimbangan"], answer: 2, solution: "1. Katalis mempercepat reaksi maju maupun reaksi balik dengan faktor yang sama besar. 2. Karena keduanya dipercepat sama besar, posisi kesetimbangan dan nilai $K$ tidak berubah. 3. Jadi katalis hanya mempercepat tercapainya kesetimbangan tanpa menggeser posisinya." },
{ q: "Diketahui $v = k[\\text{A}]^2$ dengan $k = 0{,}5\\ \\text{M}^{-1}\\text{s}^{-1}$. Jika $[\\text{A}] = 0{,}2\\ \\text{M}$, laju reaksi adalah ...", options: ["0,2 M/s", "0,02 M/s", "0,002 M/s", "2 M/s"], answer: 1, solution: "1. Diketahui $k = 0{,}5\\ \\text{M}^{-1}\\text{s}^{-1}$ dan $[\\text{A}] = 0{,}2\\ \\text{M}$. 2. Substitusi ke persamaan laju: $v = 0{,}5 \\times (0{,}2)^2 = 0{,}5 \\times 0{,}04$. 3. Jadi $v = 0{,}02\\ \\text{M/s}$." },
{ q: "Energi aktivasi $(E_a)$ suatu reaksi didefinisikan sebagai ...", options: ["total energi yang dimiliki semua partikel", "energi yang dilepaskan saat reaksi berlangsung", "selisih energi produk dan pereaksi", "energi minimum yang harus dimiliki partikel agar tumbukannya efektif"], answer: 3, solution: "1. Agar tumbukan menghasilkan reaksi, partikel harus memiliki energi kinetik yang cukup untuk memutuskan ikatan lama. 2. Batas energi minimum inilah yang disebut energi aktivasi. 3. Jadi $E_a$ adalah energi minimum yang harus dimiliki partikel agar tumbukannya efektif." },
{ q: "Reaksi $\\text{N}_2 + 3\\text{H}_2 \\rightleftharpoons 2\\text{NH}_3$. Pada keadaan setimbang $[\\text{N}_2] = 0{,}5\\ \\text{M}$, $[\\text{H}_2] = 0{,}2\\ \\text{M}$, $[\\text{NH}_3] = 0{,}4\\ \\text{M}$. Nilai $K_c$ adalah ...", options: ["40", "4", "0,4", "400"], answer: 0, solution: "1. Ungkapan $K_c = \\frac{[\\text{NH}_3]^2}{[\\text{N}_2][\\text{H}_2]^3}$. 2. Substitusi: $K_c = \\frac{(0{,}4)^2}{(0{,}5)(0{,}2)^3} = \\frac{0{,}16}{(0{,}5)(0{,}008)} = \\frac{0{,}16}{0{,}004}$. 3. Jadi $K_c = 40$." },
{ q: "Hubungan $K_p$ dan $K_c$ dinyatakan sebagai $K_p = K_c(RT)^{\\Delta n}$. Untuk reaksi $\\text{N}_2 + 3\\text{H}_2 \\rightleftharpoons 2\\text{NH}_3$, nilai $\\Delta n$ adalah ...", options: ["+4", "+2", "−2", "0"], answer: 2, solution: "1. $\\Delta n$ = jumlah koefisien gas produk dikurangi jumlah koefisien gas pereaksi. 2. Koefisien produk $= 2$ (NH₃), jumlah koefisien pereaksi $= 1 + 3 = 4$. 3. $\\Delta n = 2 - 4 = -2$." },
{ q: "Pada reaksi $\\text{N}_2(g) + 3\\text{H}_2(g) \\rightleftharpoons 2\\text{NH}_3(g)$, jika tekanan sistem dinaikkan, kesetimbangan bergeser ke arah ...", options: ["pereaksi karena koefisiennya lebih besar", "produk karena jumlah koefisiennya lebih kecil", "tidak bergeser karena katalis tidak ada", "pereaksi dan produk sama banyak"], answer: 1, solution: "1. Menurut asas Le Chatelier, kenaikan tekanan menggeser kesetimbangan ke arah jumlah koefisien (mol gas) yang lebih kecil. 2. Jumlah koefisien pereaksi $= 4$, sedangkan produk $= 2$. 3. Karena koefisien produk lebih kecil, kesetimbangan bergeser ke arah produk (kanan)." },
{ q: "Reaksi $2\\text{SO}_2 + \\text{O}_2 \\rightleftharpoons 2\\text{SO}_3$ $\\Delta H = -198\\ \\text{kJ}$ (eksoterm). Jika suhu dinaikkan, kesetimbangan bergeser ke arah ...", options: ["produk karena reaksi dipercepat", "tidak bergeser", "tetap karena $K$ tidak berubah", "pereaksi karena sistem menyerap kalor tambahan"], answer: 3, solution: "1. Reaksi ke kanan (pembentukan SO₃) bersifat eksoterm, artinya melepaskan kalor. 2. Menurut Le Chatelier, penambahan kalor (suhu naik) menggeser kesetimbangan ke arah reaksi endoterm, yaitu reaksi balik. 3. Jadi kesetimbangan bergeser ke arah pereaksi (kiri)." },
{ q: "Pernyataan yang BENAR tentang tetapan kesetimbangan $(K)$ adalah ...", options: ["nilai $K$ hanya berubah jika suhu diubah", "nilai $K$ berubah jika konsentrasi diubah", "nilai $K$ berubah jika tekanan diubah", "nilai $K$ berubah jika katalis ditambahkan"], answer: 0, solution: "1. Tetapan kesetimbangan diturunkan dari perbandingan laju reaksi maju dan balik yang sama-sama bergantung pada suhu. 2. Perubahan konsentrasi, tekanan, atau penambahan katalis hanya menggeser posisi kesetimbangan, bukan nilai $K$. 3. Jadi nilai $K$ hanya berubah jika suhu diubah." },
{ q: "Reaksi $\\text{N}_2\\text{O}_4(g) \\rightleftharpoons 2\\text{NO}_2(g)$. Mula-mula terdapat $1$ mol N₂O₄ dan saat setimbang $0{,}4$ mol telah terurai. Derajat disosiasi $(\\alpha)$ N₂O₄ adalah ...", options: ["0,2", "0,8", "0,4", "0,6"], answer: 2, solution: "1. Derajat disosiasi $\\alpha = \\frac{\\text{mol terurai}}{\\text{mol mula-mula}}$. 2. Mol terurai $= 0{,}4\\ \\text{mol}$, mol mula-mula $= 1\\ \\text{mol}$. 3. $\\alpha = \\frac{0{,}4}{1} = 0{,}4$." },
{ q: "Reaksi $\\text{A} + \\text{B} \\rightleftharpoons \\text{C}$. Saat setimbang $[\\text{A}] = [\\text{B}] = 0{,}5\\ \\text{M}$ dan $[\\text{C}] = 2\\ \\text{M}$. Nilai $K_c$ adalah ...", options: ["4", "8", "2", "16"], answer: 1, solution: "1. Ungkapan $K_c = \\frac{[\\text{C}]}{[\\text{A}][\\text{B}]}$. 2. Substitusi: $K_c = \\frac{2}{(0{,}5)(0{,}5)} = \\frac{2}{0{,}25}$. 3. Jadi $K_c = 8$." },
{ q: "Jika hasil bagi reaksi $(Q)$ lebih kecil dari tetapan kesetimbangan $(K)$, maka ...", options: ["sistem sudah setimbang", "reaksi bergeser ke arah pereaksi", "reaksi berhenti", "reaksi bergeser ke arah produk hingga $Q = K$"], answer: 3, solution: "1. $Q$ menyatakan perbandingan konsentrasi saat ini, sedangkan $K$ adalah perbandingan saat setimbang. 2. Jika $Q < K$, artinya jumlah produk masih kurang dibandingkan keadaan setimbang. 3. Reaksi bersih bergerak ke kanan (membentuk produk) hingga $Q = K$." },
{ q: "Reaksi $\\text{PCl}_5(g) \\rightleftharpoons \\text{PCl}_3(g) + \\text{Cl}_2(g)$. Jika volume wadah diperbesar, kesetimbangan bergeser ke arah ...", options: ["produk karena jumlah koefisien gasnya lebih besar", "pereaksi karena tekanannya turun", "tidak bergeser karena $\\Delta n = 0$", "produk sekaligus pereaksi"], answer: 0, solution: "1. Memperbesar volume berarti menurunkan tekanan sistem. 2. Menurut Le Chatelier, penurunan tekanan menggeser kesetimbangan ke arah jumlah koefisien gas yang lebih besar. 3. Koefisien produk $= 2$ lebih besar dari koefisien pereaksi $= 1$, jadi bergeser ke arah produk (kanan)." },
{ q: "Pada reaksi $\\text{H}_2 + \\text{I}_2 \\rightleftharpoons 2\\text{HI}$ yang setimbang, jika ke dalam sistem ditambahkan gas H₂, maka ...", options: ["kesetimbangan tidak bergeser", "kesetimbangan bergeser ke arah produk", "kesetimbangan bergeser ke arah pereaksi", "nilai $K$ menjadi lebih besar"], answer: 1, solution: "1. Penambahan H₂ menaikkan konsentrasi salah satu pereaksi. 2. Menurut Le Chatelier, sistem mengurangi kelebihan tersebut dengan menggeser kesetimbangan menjauhi zat yang ditambahkan. 3. Jadi kesetimbangan bergeser ke arah produk (kanan) dan terbentuk lebih banyak HI." },
{ q: "Untuk reaksi kesetimbangan $\\text{N}_2\\text{O}_4(g) \\rightleftharpoons 2\\text{NO}_2(g)$ yang bersifat endoterm ($\\Delta H = +58\\ \\text{kJ}$), apabila suhu dinaikkan maka kesetimbangan bergeser ke arah ...", options: ["pereaksi karena kalor dibuang", "produk karena reaksi ke kanan menyerap kalor", "tidak bergeser karena $K$ tetap", "pereaksi dan produk seimbang"], answer: 1, solution: "1. Reaksi ke kanan bersifat endoterm (menyerap kalor, $\\Delta H$ positif). 2. Menurut Le Chatelier, kenaikan suhu (penambahan kalor) menggeser kesetimbangan ke arah reaksi yang menyerap kalor. 3. Jadi bergeser ke arah produk (kanan); warna cokelat gas NO₂ bertambah." },
{ q: "Reaksi $2\\text{SO}_2(g) + \\text{O}_2(g) \\rightleftharpoons 2\\text{SO}_3(g)$. Saat setimbang tekanan parsial $p_{\\text{SO}_2} = 0{,}2\\ \\text{atm}$, $p_{\\text{O}_2} = 0{,}5\\ \\text{atm}$, $p_{\\text{SO}_3} = 0{,}4\\ \\text{atm}$. Nilai $K_p$ adalah ...", options: ["4", "16", "2", "8"], answer: 3, solution: "1. Ungkapan $K_p = \\frac{(p_{\\text{SO}_3})^2}{(p_{\\text{SO}_2})^2 (p_{\\text{O}_2})}$. 2. Substitusi: $K_p = \\frac{(0{,}4)^2}{(0{,}2)^2(0{,}5)} = \\frac{0{,}16}{(0{,}04)(0{,}5)} = \\frac{0{,}16}{0{,}02}$. 3. Jadi $K_p = 8$." },
{ q: "Sebanyak $2$ mol gas HI terdisosiasi menurut $2\\text{HI} \\rightleftharpoons \\text{H}_2 + \\text{I}_2$. Jika yang terurai $0{,}5$ mol, derajat disosiasi HI adalah ...", options: ["0,25", "0,5", "2", "0,125"], answer: 0, solution: "1. $\\alpha = \\frac{\\text{mol terurai}}{\\text{mol mula-mula}}$. 2. Mol terurai $= 0{,}5\\ \\text{mol}$, mol mula-mula $= 2\\ \\text{mol}$. 3. $\\alpha = \\frac{0{,}5}{2} = 0{,}25$." },
{ q: "Untuk reaksi heterogen $\\text{CaCO}_3(s) \\rightleftharpoons \\text{CaO}(s) + \\text{CO}_2(g)$, ungkapan $K_c$ yang tepat adalah ...", options: ["$K_c = [\\text{CaO}][\\text{CO}_2]$", "$K_c = \\frac{[\\text{CaCO}_3]}{[\\text{CaO}][\\text{CO}_2]}$", "$K_c = [\\text{CO}_2]$", "$K_c = \\frac{[\\text{CaO}]}{[\\text{CaCO}_3]}$"], answer: 2, solution: "1. Pada kesetimbangan heterogen, zat padat murni tidak dimasukkan dalam ungkapan $K$ karena konsentrasinya tetap. 2. CaCO₃ dan CaO berwujud padat $(s)$, hanya CO₂ yang berwujud gas. 3. Jadi $K_c = [\\text{CO}_2]$." },
{ q: "Derajat disosiasi $(\\alpha)$ didefinisikan sebagai ...", options: ["perbandingan mol zat yang menguap terhadap mol total", "perbandingan mol zat yang terurai terhadap mol mula-mula", "perbandingan massa produk terhadap massa pereaksi", "perbandingan tekanan parsial terhadap tekanan total"], answer: 1, solution: "1. Disosiasi adalah peristiwa terurainya suatu zat menjadi zat-zat yang lebih sederhana. 2. Derajat disosiasi menyatakan fraksi zat yang terurai dari jumlah awalnya. 3. Jadi $\\alpha = \\frac{\\text{mol terurai}}{\\text{mol mula-mula}}$, nilainya antara $0$ dan $1$." },
{ q: "Pada industri pembuatan amonia $\\text{N}_2 + 3\\text{H}_2 \\rightleftharpoons 2\\text{NH}_3$ dengan $\\Delta H$ negatif, kondisi yang menguntungkan perolehan NH₃ adalah ...", options: ["suhu tinggi dan tekanan rendah", "suhu tinggi dan tekanan tinggi", "suhu rendah dan tekanan rendah", "suhu rendah dan tekanan tinggi"], answer: 3, solution: "1. Reaksi ke kanan bersifat eksoterm ($\\Delta H$ negatif) dan jumlah koefisien gas produk ($2$) lebih kecil daripada pereaksi ($4$). 2. Suhu rendah menggeser kesetimbangan eksoterm ke arah produk; tekanan tinggi menggeser ke arah koefisien kecil (produk). 3. Jadi kondisi optimum: suhu rendah dan tekanan tinggi." },
{ q: "Menurut teori Bronsted-Lowry, asam adalah zat yang ...", options: ["menghasilkan ion OH⁻ dalam air", "mendonor proton (H⁺) kepada zat lain", "menerima proton (H⁺) dari zat lain", "mendonor pasangan elektron"], answer: 1, solution: "1. Teori Bronsted-Lowry mendefinisikan asam-basa berdasarkan serah terima proton (H⁺). 2. Asam adalah spesi yang mendonorkan proton, sedangkan basa adalah spesi yang menerima proton. 3. Contoh: pada $\\text{HCl} + \\text{NH}_3 \\to \\text{NH}_4^+ + \\text{Cl}^-$, HCl bertindak sebagai asam karena mendonor H⁺." },
{ q: "Pada reaksi $\\text{NH}_4^+ + \\text{H}_2\\text{O} \\rightleftharpoons \\text{NH}_3 + \\text{H}_3\\text{O}^+$, pasangan asam-basa konjugasi yang tepat adalah ...", options: ["NH₄⁺ dengan H₂O", "H₃O⁺ dengan H₂O", "NH₄⁺ dengan NH₃", "NH₃ dengan H₂O"], answer: 2, solution: "1. Pasangan konjugasi adalah dua spesi yang hanya berbeda satu proton (H⁺). 2. NH₄⁺ mendonor satu H⁺ menjadi NH₃, jadi NH₄⁺ (asam) berpasangan dengan NH₃ (basa konjugasinya). 3. Pasangan konjugasi lainnya adalah H₃O⁺ (asam) dengan H₂O (basa)." },
{ q: "Menurut teori asam-basa Lewis, asam adalah spesi yang ...", options: ["menerima (akseptor) pasangan elektron", "mendonor pasangan elektron", "menghasilkan ion H⁺ dalam air", "menghasilkan ion OH⁻ dalam air"], answer: 0, solution: "1. Teori Lewis mendefinisikan asam-basa berdasarkan serah terima pasangan elektron. 2. Asam Lewis adalah akseptor (penerima) pasangan elektron, sedangkan basa Lewis adalah donor pasangan elektron. 3. Contoh: BF₃ (asam Lewis) menerima pasangan elektron dari NH₃ (basa Lewis)." },
{ q: "Diketahui $K_a$ CH₃COOH $= 1 \\times 10^{-5}$. pH larutan CH₃COOH $0{,}1\\ \\text{M}$ adalah ...", options: ["1", "5", "2", "3"], answer: 3, solution: "1. CH₃COOH adalah asam lemah: $[\\text{H}^+] = \\sqrt{K_a \\times M} = \\sqrt{(1 \\times 10^{-5})(0{,}1)}$. 2. $[\\text{H}^+] = \\sqrt{1 \\times 10^{-6}} = 1 \\times 10^{-3}\\ \\text{M}$. 3. $pH = -\\log(10^{-3}) = 3$." },
{ q: "Diketahui $K_b$ NH₃ $= 1 \\times 10^{-5}$. pH larutan NH₃ $0{,}01\\ \\text{M}$ adalah ...", options: ["12", "10,5", "9", "3,5"], answer: 1, solution: "1. NH₃ adalah basa lemah: $[\\text{OH}^-] = \\sqrt{K_b \\times M} = \\sqrt{(1 \\times 10^{-5})(0{,}01)} = \\sqrt{10^{-7}} = 3{,}16 \\times 10^{-4}\\ \\text{M}$. 2. $pOH = -\\log(3{,}16 \\times 10^{-4}) = 3{,}5$. 3. $pH = 14 - pOH = 14 - 3{,}5 = 10{,}5$." },
{ q: "Diketahui larutan Ba(OH)₂ $0{,}05\\ \\text{M}$ (basa kuat bervalensi 2). Nilai pH larutan tersebut adalah ...", options: ["13", "12", "1", "2"], answer: 0, solution: "1. Ba(OH)₂ adalah basa kuat bervalensi $2$: $[\\text{OH}^-] = 2 \\times 0{,}05\\ \\text{M} = 0{,}1\\ \\text{M} = 10^{-1}\\ \\text{M}$. 2. $pOH = -\\log[\\text{OH}^-] = -\\log 10^{-1} = 1$. 3. $pH = 14 - 1 = 13$." },
{ q: "Garam CH₃COONa dilarutkan dalam air menghasilkan larutan bersifat basa karena ...", options: ["ion Na⁺ terhidrolisis menghasilkan H⁺", "ion CH₃COO⁻ berasal dari asam lemah sehingga terhidrolisis menghasilkan OH⁻", "semua garam selalu bersifat basa", "air terurai menjadi H⁺ dan OH⁻"], answer: 1, solution: "1. CH₃COONa berasal dari asam lemah (CH₃COOH) dan basa kuat (NaOH). 2. Ion CH₃COO⁻ (basa konjugasi dari asam lemah) bereaksi dengan air: $\\text{CH}_3\\text{COO}^- + \\text{H}_2\\text{O} \\rightleftharpoons \\text{CH}_3\\text{COOH} + \\text{OH}^-$. 3. Terbentuknya ion OH⁻ membuat larutan bersifat basa $(pH > 7)$." },
{ q: "Larutan NH₄Cl $0{,}1\\ \\text{M}$ bersifat asam. Hal ini disebabkan oleh ...", options: ["ion Cl⁻ yang terhidrolisis", "air yang bersifat asam", "NH₄Cl termasuk asam kuat", "ion NH₄⁺ yang terhidrolisis menghasilkan ion H⁺"], answer: 3, solution: "1. NH₄Cl berasal dari asam kuat (HCl) dan basa lemah (NH₃). 2. Ion NH₄⁺ (asam konjugasi dari basa lemah) terhidrolisis: $\\text{NH}_4^+ + \\text{H}_2\\text{O} \\rightleftharpoons \\text{NH}_3 + \\text{H}_3\\text{O}^+$. 3. Terbentuknya ion H₃O⁺/H⁺ membuat larutan bersifat asam $(pH < 7)$." },
{ q: "Diketahui $K_a$ CH₃COOH $= 10^{-5}$. pH larutan CH₃COONa $0{,}1\\ \\text{M}$ adalah ...", options: ["5", "9", "4", "10"], answer: 1, solution: "1. Tetapan hidrolisis anion: $K_h = \\frac{K_w}{K_a} = \\frac{10^{-14}}{10^{-5}} = 10^{-9}$. 2. $[\\text{OH}^-] = \\sqrt{K_h \\times M} = \\sqrt{10^{-9} \\times 0{,}1} = \\sqrt{10^{-10}} = 10^{-5}\\ \\text{M}$, sehingga $pOH = 5$. 3. $pH = 14 - 5 = 9$." },
{ q: "Campuran berikut yang merupakan larutan penyangga (buffer) adalah ...", options: ["CH₃COOH dan CH₃COONa", "HCl dan NaCl", "NaOH dan NaCl", "H₂SO₄ dan Na₂SO₄"], answer: 0, solution: "1. Larutan penyangga terdiri dari asam lemah dengan basa konjugasinya (garamnya), atau basa lemah dengan asam konjugasinya. 2. CH₃COOH (asam lemah) $+$ CH₃COONa (garam yang mengandung basa konjugasinya) memenuhi syarat tersebut. 3. HCl, NaOH, dan H₂SO₄ adalah asam/basa kuat yang tidak membentuk sistem penyangga." },
{ q: "Suatu larutan penyangga mengandung CH₃COOH dan CH₃COONa dengan konsentrasi sama besar. Diketahui $K_a = 10^{-5}$. pH larutan tersebut adalah ...", options: ["4", "6", "5", "7"], answer: 2, solution: "1. Gunakan persamaan Henderson-Hasselbalch: $pH = pK_a + \\log\\frac{[\\text{garam}]}{[\\text{asam}]}$. 2. Karena $[\\text{garam}] = [\\text{asam}]$, maka $\\log 1 = 0$ dan $pK_a = -\\log 10^{-5} = 5$. 3. Jadi $pH = 5 + 0 = 5$." },
{ q: "Pasangan zat yang dapat membentuk larutan penyangga basa adalah ...", options: ["HCl dan NH₄Cl", "CH₃COOH dan CH₃COONa", "NaOH dan CH₃COONa", "NH₃ dan NH₄Cl"], answer: 3, solution: "1. Penyangga basa tersusun dari basa lemah dan asam konjugasinya (garamnya). 2. NH₃ adalah basa lemah dan NH₄Cl adalah garam yang mengandung asam konjugasinya (NH₄⁺). 3. Jadi pasangan NH₃ dan NH₄Cl membentuk larutan penyangga basa." },
{ q: "Pada titrasi asam kuat dengan basa kuat, pH pada titik ekuivalen adalah ...", options: ["kurang dari 7", "lebih dari 7", "bergantung pada indikator", "7"], answer: 3, solution: "1. Pada titik ekuivalen, mol H⁺ dari asam kuat tepat habis bereaksi dengan mol OH⁻ dari basa kuat. 2. Garam yang terbentuk (misalnya NaCl) tidak terhidrolisis. 3. Larutan bersifat netral sehingga $pH = 7$." },
{ q: "Pada titrasi CH₃COOH (asam lemah) dengan NaOH (basa kuat), pH pada titik ekuivalen ...", options: ["lebih dari 7 karena terbentuk garam yang terhidrolisis basa", "sama dengan 7", "kurang dari 7", "sama dengan 0"], answer: 0, solution: "1. Pada titik ekuivalen terbentuk garam CH₃COONa. 2. Anion CH₃COO⁻ berasal dari asam lemah sehingga terhidrolisis menghasilkan ion OH⁻. 3. Akibatnya larutan bersifat basa dan $pH > 7$." },
{ q: "Indikator yang tepat untuk titrasi asam lemah dengan basa kuat (titik ekuivalen $pH > 7$) adalah ...", options: ["metil jingga (rentang $3{,}1–4{,}4$)", "bromtimol biru (rentang $6{,}0–7{,}6$)", "fenolftalein (rentang $8{,}3–10{,}0$)", "kertas lakmus"], answer: 2, solution: "1. Indikator dipilih yang rentang perubahan warnanya mencakup pH titik ekuivalen. 2. Titik ekuivalen titrasi asam lemah $-$ basa kuat berada pada $pH > 7$. 3. Fenolftalein (rentang $8{,}3–10{,}0$) mencakup daerah tersebut, sedangkan metil jingga cocok untuk titik ekuivalen yang bersifat asam." },
{ q: "Asam nitrat (HNO₃) $0{,}02\\ \\text{M}$ merupakan asam kuat bervalensi 1. pH larutan tersebut adalah ...", options: ["2", "1,7", "1,3", "12,3"], answer: 1, solution: "1. HNO₃ adalah asam kuat bervalensi $1$: $[\\text{H}^+] = 0{,}02\\ \\text{M} = 2 \\times 10^{-2}\\ \\text{M}$. 2. $pH = -\\log(2 \\times 10^{-2}) = 2 - \\log 2 = 2 - 0{,}3$. 3. Jadi $pH = 1{,}7$." },
{ q: "Larutan Ca(OH)₂ $0{,}005\\ \\text{M}$ merupakan basa kuat bervalensi 2. pH larutan ini adalah ...", options: ["12", "11", "2", "13"], answer: 0, solution: "1. Ca(OH)₂ adalah basa kuat bervalensi $2$: $[\\text{OH}^-] = 2 \\times 0{,}005\\ \\text{M} = 0{,}01\\ \\text{M} = 10^{-2}\\ \\text{M}$. 2. $pOH = -\\log 10^{-2} = 2$. 3. $pH = 14 - 2 = 12$." },
{ q: "Suatu larutan memiliki $[\\text{H}^+] = 2 \\times 10^{-4}\\ \\text{M}$. pH larutan tersebut adalah ...", options: ["4", "3,3", "3,7", "4,7"], answer: 2, solution: "1. $pH = -\\log[\\text{H}^+] = -\\log(2 \\times 10^{-4})$. 2. $pH = 4 - \\log 2 = 4 - 0{,}3$. 3. Jadi $pH = 3{,}7$." },
{ q: "Larutan HCl $0{,}1\\ \\text{M}$ diencerkan $10$ kali dengan air. pH larutan setelah pengenceran adalah ...", options: ["tetap 1", "2", "0,1", "3"], answer: 1, solution: "1. Pengenceran $10$ kali membuat konsentrasi menjadi $\\frac{0{,}1}{10} = 0{,}01\\ \\text{M}$. 2. HCl adalah asam kuat: $[\\text{H}^+] = 0{,}01\\ \\text{M} = 10^{-2}\\ \\text{M}$. 3. $pH = -\\log 10^{-2} = 2$ (pH naik $1$ satuan setiap pengenceran $10$ kali)." },
{ q: "Larutan penyangga dibuat dari $0{,}1\\ \\text{M}$ CH₃COOH dan $0{,}2\\ \\text{M}$ CH₃COONa ($K_a = 10^{-5}$). pH larutan tersebut adalah ...", options: ["4,7", "5", "5,3", "6"], answer: 3, solution: "1. $pH = pK_a + \\log\\frac{[\\text{garam}]}{[\\text{asam}]} = 5 + \\log\\frac{0{,}2}{0{,}1}$. 2. $\\log\\frac{0{,}2}{0{,}1} = \\log 2 = 0{,}3$. 3. Jadi $pH = 5 + 0{,}3 = 5{,}3$." },
{ q: "Dengan aturan bilangan oksidasi (K = +1, O = −2), bilangan oksidasi Cr dalam K₂Cr₂O₇ adalah ...", options: ["+4", "+6", "+3", "+5"], answer: 1, solution: "1. Aturan biloks: K $= +1$, O $= -2$. Misalkan biloks Cr $= x$. 2. $2(+1) + 2x + 7(-2) = 0$. 3. $2 + 2x - 14 = 0$, sehingga $2x = 12$ dan $x = +6$." },
{ q: "Dalam HNO₃, jika bilangan oksidasi H = +1 dan O = −2, bilangan oksidasi N adalah ...", options: ["+3", "−3", "+4", "+5"], answer: 3, solution: "1. Aturan biloks: H $= +1$, O $= -2$. Misalkan biloks N $= x$. 2. $(+1) + x + 3(-2) = 0$. 3. $1 + x - 6 = 0$, sehingga $x = +5$." },
{ q: "Tentukan bilangan oksidasi P dalam H₃PO₄ (diketahui H = +1, O = −2): ...", options: ["+5", "+3", "−5", "+4"], answer: 0, solution: "1. Aturan biloks: H $= +1$, O $= -2$. Misalkan biloks P $= x$. 2. $3(+1) + x + 4(-2) = 0$. 3. $3 + x - 8 = 0$, sehingga $x = +5$." },
{ q: "Reaksi $\\text{Al} + \\text{HCl} \\to \\text{AlCl}_3 + \\text{H}_2$ yang sudah setara adalah $2\\text{Al} + 6\\text{HCl} \\to 2\\text{AlCl}_3 + 3\\text{H}_2$. Koefisien HCl adalah ...", options: ["2", "3", "6", "4"], answer: 2, solution: "1. Setarakan Al: $2\\text{Al} \\to 2\\text{AlCl}_3$ (2 Al di kedua ruas). 2. Setarakan Cl: $2\\text{AlCl}_3$ mengandung $6$ Cl, jadi diperlukan $6\\text{HCl}$. 3. Cek H: $6$ H di kiri menjadi $3\\text{H}_2$ di kanan, sudah setara. Jadi koefisien HCl $= 6$." },
{ q: "Pada reaksi redoks $\\text{Cl}_2 + 2\\text{NaBr} \\to 2\\text{NaCl} + \\text{Br}_2$, spesi yang mengalami reduksi (bertindak sebagai oksidator) adalah ...", options: ["NaBr", "Cl₂", "NaCl", "Br₂"], answer: 1, solution: "1. Oksidator adalah zat yang mengalami reduksi (bilangan oksidasi turun). 2. Biloks Cl turun dari $0$ (dalam Cl₂) menjadi $-1$ (dalam NaCl), sedangkan biloks Br naik dari $-1$ menjadi $0$. 3. Jadi oksidatornya adalah Cl₂." },
{ q: "Dalam deret volta, Zn terletak di sebelah kiri Cu. Hal ini berarti ...", options: ["Zn lebih mudah teroksidasi (reduktor lebih kuat) daripada Cu", "Cu lebih mudah teroksidasi daripada Zn", "Zn tidak dapat bereaksi dengan ion Cu²⁺", "Cu adalah oksidator paling lemah"], answer: 0, solution: "1. Deret volta disusun berdasarkan kecenderungan melepas elektron (kemudahan teroksidasi) yang makin berkurang dari kiri ke kanan. 2. Zn berada di kiri Cu berarti Zn lebih mudah teroksidasi daripada Cu. 3. Jadi Zn merupakan reduktor yang lebih kuat daripada Cu." },
{ q: "Diketahui $E^\\circ(\\text{Cu}^{2+}/\\text{Cu}) = +0{,}34\\ \\text{V}$ dan $E^\\circ(\\text{Zn}^{2+}/\\text{Zn}) = -0{,}76\\ \\text{V}$. Potensial sel volta Zn−Cu adalah ...", options: ["−1,10 V", "0,42 V", "1,86 V", "1,10 V"], answer: 3, solution: "1. Pada sel Zn−Cu, Cu²⁺ tereduksi di katode dan Zn teroksidasi di anode. 2. $E^\\circ_{\\text{sel}} = E^\\circ_{\\text{katode}} - E^\\circ_{\\text{anode}} = (+0{,}34) - (-0{,}76)$. 3. Jadi $E^\\circ_{\\text{sel}} = 1{,}10\\ \\text{V}$." },
{ q: "Notasi sel volta untuk reaksi $\\text{Zn} + \\text{Cu}^{2+} \\to \\text{Zn}^{2+} + \\text{Cu}$ yang tepat adalah ...", options: ["Cu|Cu²⁺||Zn²⁺|Zn", "Zn²⁺|Zn||Cu|Cu²⁺", "Zn|Zn²⁺||Cu²⁺|Cu", "Cu²⁺|Cu||Zn|Zn²⁺"], answer: 2, solution: "1. Notasi sel ditulis dengan anode (oksidasi) di kiri dan katode (reduksi) di kanan, dipisahkan jembatan garam $||$. 2. Zn mengalami oksidasi (anode), sedangkan Cu²⁺ mengalami reduksi (katode). 3. Jadi notasi yang tepat adalah $\\text{Zn}|\\text{Zn}^{2+}||\\text{Cu}^{2+}|\\text{Cu}$." },
{ q: "Pada elektrolisis lelehan (cairan) NaCl dengan elektrode grafit, zat yang terbentuk di katode adalah ...", options: ["gas Cl₂", "logam Na", "gas H₂", "gas O₂"], answer: 1, solution: "1. Di katode selalu terjadi reaksi reduksi (penangkapan elektron). 2. Lelehan NaCl hanya mengandung ion Na⁺ dan Cl⁻, tidak ada air. 3. Ion Na⁺ tereduksi: $\\text{Na}^+ + e^- \\to \\text{Na}$, jadi di katode terbentuk logam natrium." },
{ q: "Larutan Na₂SO₄ dielektrolisis dengan elektrode Pt. Gas yang terbentuk di katode adalah ...", options: ["H₂", "O₂", "SO₂", "SO₃"], answer: 0, solution: "1. Kation Na⁺ berasal dari golongan IA sehingga sukar tereduksi; yang tereduksi adalah air: $2\\text{H}_2\\text{O} + 2e^- \\to \\text{H}_2 + 2\\text{OH}^-$. 2. Di katode terjadi reaksi reduksi. 3. Jadi gas yang terbentuk di katode adalah H₂ (di anode terbentuk O₂)." },
{ q: "Arus listrik $2$ A dialirkan selama $9650$ detik melalui larutan AgNO₃. Massa perak yang mengendap di katode adalah ... (massa ekuivalen Ag $= 108\\ \\text{g}$, $F = 96500\\ \\text{C/mol}$)", options: ["2,16 g", "216 g", "21,6 g", "10,8 g"], answer: 2, solution: "1. Hukum Faraday I: $w = \\frac{e \\times i \\times t}{96500}$. 2. $w = \\frac{108 \\times 2 \\times 9650}{96500} = 108 \\times \\frac{19300}{96500} = 108 \\times 0{,}2$. 3. Jadi $w = 21{,}6\\ \\text{g}$ perak." },
{ q: "Jumlah listrik yang sama dialirkan melalui larutan CuSO₄ dan Al₂(SO₄)₃ berturut-turut. Jika massa Cu yang mengendap $= 6{,}35\\ \\text{g}$ ($A_r$ Cu $= 63{,}5$), massa Al yang mengendap adalah ... ($A_r$ Al $= 27$)", options: ["5,4 g", "0,9 g", "3,6 g", "1,8 g"], answer: 3, solution: "1. Hukum Faraday II: $\\frac{w_{\\text{Al}}}{w_{\\text{Cu}}} = \\frac{e_{\\text{Al}}}{e_{\\text{Cu}}}$, dengan massa ekuivalen $e = \\frac{A_r}{\\text{jumlah elektron}}$. 2. $e_{\\text{Cu}} = \\frac{63{,}5}{2} = 31{,}75$ dan $e_{\\text{Al}} = \\frac{27}{3} = 9$. 3. $w_{\\text{Al}} = 6{,}35 \\times \\frac{9}{31{,}75} = 6{,}35 \\times 0{,}2 = 1{,}8\\ \\text{g}$." },
{ q: "Larutan NaCl dielektrolisis dengan elektrode karbon (C). Zat yang terbentuk di anode adalah ...", options: ["logam Na", "gas H₂", "gas Cl₂", "gas O₂"], answer: 2, solution: "1. Di anode selalu terjadi reaksi oksidasi (pelepasan elektron). 2. Elektrode C adalah elektrode inert sehingga anion Cl⁻ teroksidasi: $2\\text{Cl}^- \\to \\text{Cl}_2 + 2e^-$. 3. Jadi di anode terbentuk gas Cl₂." },
{ q: "Pipa besi bawah tanah dilindungi dari korosi dengan cara dihubungkan ke logam magnesium. Cara ini disebut ...", options: ["proteksi katodik (anode korban)", "pelapisan cat", "pembuatan paduan (alloy)", "pengecatan ulang berkala"], answer: 0, solution: "1. Magnesium lebih mudah teroksidasi (lebih reaktif) daripada besi. 2. Mg bertindak sebagai anode korban yang terkorosi menggantikan besi, sehingga besi menjadi katode yang terlindungi. 3. Cara ini disebut proteksi katodik (anode korban)." },
{ q: "Untuk ion ClO₃⁻ (bilangan oksidasi O = −2), bilangan oksidasi Cl adalah ...", options: ["+3", "+7", "+5", "+1"], answer: 2, solution: "1. Aturan biloks: O $= -2$, dan jumlah biloks dalam suatu ion sama dengan muatannya $(-1)$. Misalkan biloks Cl $= x$. 2. $x + 3(-2) = -1$. 3. $x - 6 = -1$, sehingga $x = +5$." },
{ q: "Gugus fungsi yang menjadi ciri senyawa alkohol adalah ...", options: ["−O−", "−OH", "−CHO", "−COOH"], answer: 1, solution: "1. Alkohol adalah senyawa karbon yang mengikat gugus hidroksil. 2. Gugus fungsi alkohol ditulis $-$OH, misalnya pada etanol CH₃CH₂OH. 3. Gugus $-$O$-$ adalah eter, $-$CHO adalah aldehid, dan $-$COOH adalah asam karboksilat." },
{ q: "Etanol (CH₃CH₂OH) dan dimetil eter (CH₃OCH₃) memiliki rumus molekul sama, C₂H₆O. Keduanya merupakan ...", options: ["isomer gugus fungsi", "isomer geometri", "homolog", "polimer"], answer: 0, solution: "1. Kedua senyawa memiliki rumus molekul yang sama (C₂H₆O) tetapi gugus fungsinya berbeda ($-$OH lawan $-$O$-$). 2. Isomer yang gugus fungsinya berbeda disebut isomer gugus fungsi. 3. Jadi etanol dan dimetil eter adalah isomer gugus fungsi." },
{ q: "Perbedaan sifat antara aldehid dan keton dapat ditunjukkan dengan ...", options: ["keduanya bereaksi dengan pereaksi Tollens", "keduanya tidak bereaksi dengan pereaksi Fehling", "tidak ada pereaksi yang dapat membedakan", "aldehid mereduksi pereaksi Tollens/Fehling, sedangkan keton tidak"], answer: 3, solution: "1. Aldehid memiliki gugus $-$CHO dengan atom H yang mudah dioksidasi. 2. Aldehid mereduksi pereaksi Tollens (membentuk cermin perak) dan Fehling/Benedict (endapan merah bata), sedangkan keton tidak bereaksi. 3. Jadi uji Tollens/Fehling membedakan aldehid dari keton." },
{ q: "Gugus fungsi asam karboksilat adalah ...", options: ["−OH", "−O−", "−COOH", "−COOR"], answer: 2, solution: "1. Asam karboksilat adalah senyawa karbon bersifat asam dengan gugus karboksil. 2. Gugus fungsi asam karboksilat ditulis $-$COOH, misalnya pada asam asetat CH₃COOH. 3. Gugus $-$COOR adalah gugus fungsi ester." },
{ q: "Senyawa ester umumnya memiliki sifat khas berupa ...", options: ["bau menyengat seperti cuka", "rasa sangat asam", "bau harum seperti buah-buahan", "wujud selalu berupa gas"], answer: 2, solution: "1. Ester (R$-$COO$-$R') banyak ditemukan sebagai senyawa pewangi alami pada buah-buahan. 2. Contoh: amil asetat berbau pisang dan etil butirat berbau nanas. 3. Jadi ciri khas ester adalah bau harum seperti buah-buahan." },
{ q: "Nama IUPAC dari CH₃−CH₂−CH₂−OH adalah ...", options: ["propan-1-ol", "propan-2-ol", "etanol", "propana"], answer: 0, solution: "1. Rantai karbon terpanjang terdiri dari $3$ atom C sehingga nama dasarnya propana. 2. Gugus $-$OH terikat pada atom C nomor $1$ (dihitung dari ujung terdekat gugus fungsi). 3. Jadi namanya propan-1-ol (nama lazim: 1-propanol)." },
{ q: "Nama IUPAC dari CH₃−CH(CH₃)−CH₂−CH₃ adalah ...", options: ["n-pentana", "2-metilpropana", "3-metilbutana", "2-metilbutana"], answer: 3, solution: "1. Rantai utama terpanjang terdiri dari $4$ atom C (butana), bukan $3$. 2. Cabang metil terikat pada atom C nomor $2$ (penomoran dimulai dari ujung terdekat cabang). 3. Jadi namanya 2-metilbutana." },
{ q: "Jumlah isomer struktur dari C₄H₁₀ adalah ...", options: ["1", "3", "2", "4"], answer: 2, solution: "1. Isomer struktur adalah senyawa berumus molekul sama tetapi susunan rantai karbonnya berbeda. 2. C₄H₁₀ dapat disusun sebagai rantai lurus (n-butana) dan rantai bercabang (2-metilpropana / isobutana). 3. Jadi terdapat $2$ isomer struktur." },
{ q: "Gas etena dialirkan ke dalam air bromin. Perubahan yang terjadi adalah ...", options: ["tidak terjadi perubahan", "air bromin yang berwarna cokelat menjadi pudar (tidak berwarna)", "timbul endapan merah bata", "terbentuk gas hidrogen"], answer: 1, solution: "1. Etena (CH₂$=$CH₂) memiliki ikatan rangkap yang dapat mengalami reaksi adisi. 2. Br₂ mengadisi ikatan rangkap membentuk 1,2-dibromoetana yang tidak berwarna. 3. Warna cokelat air bromin memudar, dan reaksi ini menjadi uji khas ikatan rangkap (ketidakjenuhan)." },
{ q: "Reaksi CH₄ + Cl₂ dengan bantuan cahaya matahari menghasilkan CH₃Cl + HCl. Reaksi ini tergolong reaksi ...", options: ["substitusi", "adisi", "eliminasi", "pembakaran"], answer: 0, solution: "1. Pada reaksi ini satu atom H pada CH₄ digantikan oleh satu atom Cl. 2. Penggantian satu atom/gugus oleh atom/gugus lain disebut reaksi substitusi. 3. Jadi halogenasi alkana dengan bantuan cahaya adalah reaksi substitusi." },
{ q: "Etanol dipanaskan dengan asam sulfat pekat menghasilkan etena dan air. Reaksi ini tergolong reaksi ...", options: ["adisi", "substitusi", "oksidasi", "eliminasi (dehidrasi)"], answer: 3, solution: "1. Pada reaksi ini molekul air (H₂O) dilepaskan dari etanol sehingga terbentuk ikatan rangkap C$=$C. 2. Pelepasan molekul kecil dari suatu senyawa disertai terbentuknya ikatan rangkap disebut reaksi eliminasi. 3. Karena yang dilepas adalah air, reaksi ini disebut dehidrasi." },
{ q: "Senyawa dengan gugus fungsi $-$O$-$ di antara dua gugus alkil (misalnya CH₃OCH₃) tergolong ...", options: ["alkohol", "eter", "aldehid", "keton"], answer: 1, solution: "1. Gugus $-$O$-$ yang mengikat dua gugus alkil disebut gugus alkoksi. 2. Senyawa dengan gugus fungsi R$-$O$-$R' tergolong eter (alkoksialkana). 3. Contohnya dimetil eter (CH₃OCH₃) yang berisomer gugus fungsi dengan etanol." },

  ]
};
